INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_basic#6','math',4,2,'u6','L02','g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'sa','auto','점을 아래쪽으로 7칸 옮긴 다음 다시 위쪽으로 1칸 옮겼어요. 처음 자리보다 아래쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":2,"kind":"sa","stem":"점을 아래쪽으로 7칸 옮긴 다음 다시 위쪽으로 1칸 옮겼어요. 처음 자리보다 아래쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["아래쪽과 위쪽은 서로 되돌리는 방향이에요.","반대 방향으로 1칸 되돌아왔으니 빼요.","7 − 1 = 6칸이에요."],"variant_rule":{"alt":[{"stem":"점을 위쪽으로 5칸 옮긴 다음 다시 아래쪽으로 3칸 옮겼어요. 처음 자리보다 위쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["위쪽과 아래쪽은 서로 되돌리는 방향이에요.","반대 방향으로 3칸 되돌아왔으니 빼요.","5 − 3 = 2칸이에요."],"asset":null},{"stem":"점을 오른쪽으로 6칸 옮긴 다음 다시 오른쪽으로 4칸 옮겼어요. 처음 자리에서 오른쪽으로 모두 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["두 번 모두 오른쪽으로 옮겼어요.","같은 방향이니 더해요.","6 + 4 = 10칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_basic#7','math',4,2,'u6','L02','g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'mc','auto','점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":7,"concept":"M4-2-u6-C2","difficulty":2,"kind":"mc","stem":"점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"왼쪽으로 5칸 옮기고 위쪽으로 3칸 옮겼어요","correct":true},{"t":"왼쪽으로 3칸 옮기고 위쪽으로 5칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 5칸 옮기고 위쪽으로 3칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 5칸 옮기고 위쪽으로 4칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 왼쪽으로 5칸, 세로로 위쪽으로 3칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[144,90,"s"],"ㄴ":[54,36,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"위쪽으로 4칸 옮기고 오른쪽으로 6칸 옮겼어요","correct":true},{"t":"위쪽으로 6칸 옮기고 오른쪽으로 4칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 6칸 옮기고 위쪽으로 4칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 6칸 옮기고 위쪽으로 5칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 오른쪽으로 6칸, 세로로 위쪽으로 4칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[18,90,"n"],"ㄴ":[126,18,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"왼쪽으로 6칸 옮기고 위쪽으로 2칸 옮겼어요","correct":true},{"t":"왼쪽으로 2칸 옮기고 위쪽으로 6칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 6칸 옮기고 위쪽으로 2칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 6칸 옮기고 위쪽으로 3칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 왼쪽으로 6칸, 세로로 위쪽으로 2칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[126,90,"n"],"ㄴ":[18,54,"n"]}}