INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_basic#8','math',4,2,'u6','L02','g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'ox','auto','점을 오른쪽으로 5칸 옮긴 다음 아래쪽으로 4칸 옮긴 것과 아래쪽으로 4칸 옮긴 다음 오른쪽으로 5칸 옮긴 것은 도착하는 자리가 같아요.',ARRAY['M4-2-u6-X05']::text[],true,'{"seq":8,"concept":"M4-2-u6-C2","difficulty":2,"kind":"ox","stem":"점을 오른쪽으로 5칸 옮긴 다음 아래쪽으로 4칸 옮긴 것과 아래쪽으로 4칸 옮긴 다음 오른쪽으로 5칸 옮긴 것은 도착하는 자리가 같아요.","answer":"O","reason_options":[{"t":"말하는 순서를 바꾸어도 도착하는 자리는 같아서","correct":true},{"t":"옮기는 순서가 다르면 도착하는 자리도 달라서","mis":"M4-2-u6-X05"}],"mis":"M4-2-u6-X05","explanation":["점을 옮기면 자리만 바뀌어요.","방향과 칸 수를 함께 말하고, 두 방향은 순서를 바꾸어도 도착이 같아요.","반대 방향으로 옮기면 빼고, 같은 방향이면 더해요."],"variant_rule":{"alt":[{"stem":"점을 왼쪽으로 3칸 옮긴 다음 오른쪽으로 3칸 옮기면 처음 자리로 돌아와요.","answer":"O","reason_options":[{"t":"왼쪽과 오른쪽은 서로 되돌리는 방향이라서","correct":true},{"t":"3칸 + 3칸 = 6칸만큼 멀어져서","mis":"M4-2-u6-X07"}],"explanation":["점을 옮기면 자리만 바뀌어요.","방향과 칸 수를 함께 말하고, 두 방향은 순서를 바꾸어도 도착이 같아요.","반대 방향으로 옮기면 빼고, 같은 방향이면 더해요."],"asset":null},{"stem":"점을 옮기면 점의 자리와 모양이 함께 바뀌어요.","answer":"X","reason_options":[{"t":"점 자체는 그대로이고 자리만 바뀌어서","correct":true},{"t":"옮기면 모든 것이 바뀌어서","mis":"M4-2-u6-X08"}],"explanation":["점을 옮기면 자리만 바뀌어요.","방향과 칸 수를 함께 말하고, 두 방향은 순서를 바꾸어도 도착이 같아요.","반대 방향으로 옮기면 빼고, 같은 방향이면 더해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
