INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#2','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',2,'mc','auto','점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":2,"concept":"M4-2-u6-C2","difficulty":2,"kind":"mc","stem":"점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"아래쪽으로 1칸 옮기고 왼쪽으로 2칸 옮겼어요","correct":true},{"t":"아래쪽으로 2칸 옮기고 왼쪽으로 1칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 2칸 옮기고 아래쪽으로 1칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 2칸 옮기고 아래쪽으로 2칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 왼쪽으로 2칸, 세로로 아래쪽으로 1칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[72,72,"e"],"ㄴ":[36,90,"w"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"오른쪽으로 3칸 옮기고 위쪽으로 5칸 옮겼어요","correct":true},{"t":"오른쪽으로 5칸 옮기고 위쪽으로 3칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 3칸 옮기고 위쪽으로 5칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 3칸 옮기고 위쪽으로 6칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 오른쪽으로 3칸, 세로로 위쪽으로 5칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[72,108,"s"],"ㄴ":[126,18,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"아래쪽으로 2칸 옮기고 왼쪽으로 4칸 옮겼어요","correct":true},{"t":"아래쪽으로 4칸 옮기고 왼쪽으로 2칸 옮겼어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 4칸 옮기고 아래쪽으로 2칸 옮겼어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 4칸 옮기고 아래쪽으로 3칸 옮겼어요","mis":"M4-2-u6-X03"}],"explanation":["가로로 왼쪽으로 4칸, 세로로 아래쪽으로 2칸 옮겼어요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요.","방향마다 칸 수를 바르게 붙인 설명을 골라요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[90,36,"