INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#3','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'error','auto','점 ㄱ을 옮겨 점 ㄴ의 자리에 오게 했어요. 잘못 설명한 친구는 누구인가요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X21']::text[],true,'{"seq":3,"concept":"M4-2-u6-C2","difficulty":3,"kind":"error","stem":"점 ㄱ을 옮겨 점 ㄴ의 자리에 오게 했어요. 잘못 설명한 친구는 누구인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"은우 — 「아래쪽으로 2칸 옮기고 오른쪽으로 3칸 옮겼어.」","correct":true,"mis_target":"M4-2-u6-X06"},{"t":"하랑 — 「오른쪽으로 2칸 옮기고 아래쪽으로 3칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"지아 — 「아래쪽으로 3칸 옮기고 오른쪽으로 2칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"준서 — 「오른쪽으로 2 cm 옮기고 아래쪽으로 3 cm 옮겼어.」","mis":"M4-2-u6-X21"}],"explanation":["점 ㄱ은 오른쪽으로 2칸, 아래쪽으로 3칸 옮겨졌어요.","순서를 바꾸어 말해도, 칸을 cm로 말해도 맞아요.","은우는 두 방향의 칸 수를 서로 바꾸어 붙였어요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[18,18,"nw"],"ㄴ":[54,72,"se"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겨 점 ㄴ의 자리에 오게 했어요. 잘못 설명한 친구는 누구인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"하랑 — 「왼쪽으로 1칸 옮기고 아래쪽으로 3칸 옮겼어.」","correct":true,"mis_target":"M4-2-u6-X06"},{"t":"지아 — 「왼쪽으로 3칸 옮기고 아래쪽으로 1칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"준서 — 「아래쪽으로 1칸 옮기고 왼쪽으로 3칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「왼쪽으로 3 cm 옮기고 아래쪽으로 1 cm 옮겼어.」","mis":"M4-2-u6-X21"}],"explanation":["점 ㄱ은 왼쪽으로 3칸, 아래쪽으로 1칸 옮겨졌어요.","순서를 바꾸어 말해도, 칸을 cm로 말해도 맞아요.","하랑는 두 방향의 칸 수를 서로 바꾸어 붙였어요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[162,90,"e"],"ㄴ":[108,108,"w"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겨 점 ㄴ의 자리에 오게 했어요. 잘못 설명한 친구는 누구인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"지아 — 「아래쪽으로 6칸 옮기고 왼쪽으로 1칸 옮겼어.」","correct":true,"mis_target":"M4-2-u6-X06"},{"t":"준서 — 「왼쪽으로 6칸 옮기고 아래쪽으로 1칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「아래쪽으로 1칸 옮기고 왼쪽으로 6칸 옮겼어.」","mis":"M4-2-u6-X21"},{"t":"도윤 — 「왼쪽으로 6 cm 옮기고 아래쪽으로 1 cm 옮겼어.」","mis":"M4-2-u6-X21"}],"explanation":["점 ㄱ은 왼쪽으로 6칸, 아래쪽으로 1칸 옮겨졌어요.","순서를 바꾸어 말해도, 칸을 cm로 말해도 맞아요.","지아는 두 방향의 칸 수를 서로 바꾸어 붙였어요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[144,90,"n"],"ㄴ":[36,108,"s"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#4','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','점 ㄴ은 점 ㄱ을 오른쪽으로 3칸 옮기고 위쪽으로 4칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X02']::text[],true,'{"seq":4,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"점 ㄴ은 점 ㄱ을 오른쪽으로 3칸 옮기고 위쪽으로 4칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"왼쪽으로 3칸 옮기고 아래쪽으로 4칸 옮겨요","correct":true},{"t":"오른쪽으로 3칸 옮기고 위쪽으로 4칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"왼쪽으로 4칸 옮기고 아래쪽으로 3칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 3칸 옮기고 위쪽으로 4칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","오른쪽의 반대는 왼쪽, 위쪽의 반대는 아래쪽이에요.","칸 수는 그대로 — 왼쪽으로 3칸 옮기고 아래쪽으로 4칸 옮기면 돼요."],"variant_rule":{"alt":[{"stem":"점 ㄴ은 점 ㄱ을 왼쪽으로 2칸 옮기고 위쪽으로 3칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"오른쪽으로 2칸 옮기고 아래쪽으로 3칸 옮겨요","correct":true},{"t":"왼쪽으로 2칸 옮기고 위쪽으로 3칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"오른쪽으로 3칸 옮기고 아래쪽으로 2칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 2칸 옮기고 위쪽으로 3칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","왼쪽의 반대는 오른쪽, 위쪽의 반대는 아래쪽이에요.","칸 수는 그대로 — 오른쪽으로 2칸 옮기고 아래쪽으로 3칸 옮기면 돼요."],"asset":null},{"stem":"점 ㄴ은 점 ㄱ을 오른쪽으로 2칸 옮기고 아래쪽으로 3칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"왼쪽으로 2칸 옮기고 위쪽으로 3칸 옮겨요","correct":true},{"t":"오른쪽으로 2칸 옮기고 아래쪽으로 3칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"왼쪽으로 3칸 옮기고 위쪽으로 2칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 2칸 옮기고 아래쪽으로 3칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","오른쪽의 반대는 왼쪽, 아래쪽의 반대는 위쪽이에요.","칸 수는 그대로 — 왼쪽으로 2칸 옮기고 위쪽으로 3칸 옮기면 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUD