INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#5','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','점 ㄴ은 어떤 점을 오른쪽으로 2칸 옮기고 아래쪽으로 1칸 옮긴 점이에요. 처음 점은 어느 것인가요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X03']::text[],true,'{"seq":5,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"점 ㄴ은 어떤 점을 오른쪽으로 2칸 옮기고 아래쪽으로 1칸 옮긴 점이에요. 처음 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X07"},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"}],"explanation":["거꾸로 생각해요 — 점 ㄴ에서 반대 방향으로 되돌려요.","왼쪽으로 2칸, 위쪽으로 1칸 옮기면 돼요.","처음 점은 점 ㄱ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄴ":[54,90,"s"],"ㄱ":[18,72,"w"],"ㄷ":[36,72,"s"],"ㄹ":[36,54,"n"],"ㅁ":[90,108,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㄴ은 어떤 점을 왼쪽으로 3칸 옮기고 위쪽으로 1칸 옮긴 점이에요. 처음 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X07"},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄱ","mis":"M4-2-u6-X03"}],"explanation":["거꾸로 생각해요 — 점 ㄴ에서 반대 방향으로 되돌려요.","오른쪽으로 3칸, 아래쪽으로 1칸 옮기면 돼요.","처음 점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄴ":[72,36,"n"],"ㄱ":[108,54,"w"],"ㄷ":[18,18,"w"],"ㄹ":[90,90,"s"],"ㅁ":[126,54,"e"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄴ은 어떤 점을 오른쪽으로 2칸 옮기고 아래쪽으로 1칸 옮긴 점이에요. 처음 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X07"},{"t":"점 ㄱ","mis":"M4-2-u6-X06"},{"t":"점 ㄹ","mis":"M4-2-u6-X03"}],"explanation":["거꾸로 생각해요 — 점 ㄴ에서 반대 방향으로 되돌려요.","왼쪽으로 2칸, 위쪽으로 1칸 옮기면 돼요.","처음 점은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄴ":[54,72,"s"],"ㄱ":[36,36,"n"],"ㄷ":[18,54,"w"],"ㄹ":[36,54,"s"],"ㅁ":[90,90,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficult