INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#6','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'sa','auto','로니가 점을 오른쪽으로 6칸, 위쪽으로 5칸, 왼쪽으로 9칸 옮겼어요. 처음 자리보다 왼쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":3,"kind":"sa","stem":"로니가 점을 오른쪽으로 6칸, 위쪽으로 5칸, 왼쪽으로 9칸 옮겼어요. 처음 자리보다 왼쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세로 위쪽으로 5칸은 가로 자리를 바꾸지 않아요.","가로로는 오른쪽으로 6칸, 왼쪽으로 9칸 — 반대 방향이니 빼요.","9 − 6 = 3 — 왼쪽으로 3칸이에요."],"variant_rule":{"alt":[{"stem":"로니가 점을 왼쪽으로 2칸, 위쪽으로 1칸, 오른쪽으로 3칸 옮겼어요. 처음 자리보다 오른쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 위쪽으로 1칸은 가로 자리를 바꾸지 않아요.","가로로는 왼쪽으로 2칸, 오른쪽으로 3칸 — 반대 방향이니 빼요.","3 − 2 = 1 — 오른쪽으로 1칸이에요."],"asset":null},{"stem":"로니가 점을 오른쪽으로 4칸, 아래쪽으로 5칸, 왼쪽으로 3칸 옮겼어요. 처음 자리보다 오른쪽으로 몇 칸 떨어진 자리인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["세로 아래쪽으로 5칸은 가로 자리를 바꾸지 않아요.","가로로는 오른쪽으로 4칸, 왼쪽으로 3칸 — 반대 방향이니 빼요.","4 − 3 = 1 — 오른쪽으로 1칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#7','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'sa','auto','점 ㄱ을 가로와 세로로만 옮겨서 점 ㄴ의 자리에 오게 했어요. 가장 짧게 옮겼다면 모두 몇 칸 옮긴 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u6-C2","difficulty":3,"kind":"sa","stem":"점 ㄱ을 가로와 세로로만 옮겨서 점 ㄴ의 자리에 오게 했어요. 가장 짧게 옮겼다면 모두 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로로 오른쪽으로 3칸 옮겨요.","세로로 아래쪽으로 1칸 옮겨요.","3 + 1 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[54,90,"w"],"ㄴ":[108,108,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 가로와 세로로만 옮겨서 점 ㄴ의 자리에 오게 했어요. 가장 짧게 옮겼다면 모두 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["가로로 왼쪽으로 3칸 옮겨요.","세로로 위쪽으로 4칸 옮겨요.","3 + 4 = 7칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[144,108,"s"],"ㄴ":[90,36,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 가로와 세로로만 옮겨서 점 ㄴ의 자리에 오게 했어요. 가장 짧게 옮겼다면 모두 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로로 오른쪽으로 3칸 옮겨요.","세로로 아래쪽으로 1칸 옮겨요.","3 + 1 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[36,54,"w"],"ㄴ":[90,72,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#8','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',4,'mc','auto','모눈 한 칸이 2 cm예요. 점 ㄱ을 점 ㄴ의 자리로 옮기려면 어떻게 옮겨야 하나요?',ARRAY['M4-2-u6-X04','M4-2-u6-X03','M4-2-u6-X02']::text[],true,'{"seq":8,"concept":"M4-2-u6-C2","difficulty":4,"kind":"mc","stem":"모눈 한 칸이 2 cm예요. 점 ㄱ을 점 ㄴ의 자리로 옮기려면 어떻게 옮겨야 하나요?","options":[{"t":"오른쪽으로 10 cm","correct":true},{"t":"오른쪽으로 5 cm","mis":"M4-2-u6-X04"},{"t":"오른쪽으로 12 cm","mis":"M4-2-u6-X03"},{"t":"왼쪽으로 10 cm","mis":"M4-2-u6-X02"}],"explanation":["먼저 칸 수를 세면 5칸이에요.","한 칸이 2 cm라서 칸 수와 cm는 같지 않아요.","5 × 2 = 10 — 오른쪽으로 10 cm예요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[18,54,"w"],"ㄴ":[108,54,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 한 칸이 3 cm예요. 점 ㄱ을 점 ㄴ의 자리로 옮기려면 어떻게 옮겨야 하나요?","options":[{"t":"왼쪽으로 6 cm","correct":true},{"t":"왼쪽으로 2 cm","mis":"M4-2-u6-X04"},{"t":"왼쪽으로 9 cm","mis":"M4-2-u6-X03"},{"t":"오른쪽으로 6 cm","mis":"M4-2-u6-X02"}],"explanation":["먼저 칸 수를 세면 2칸이에요.","한 칸이 3 cm라서 칸 수와 cm는 같지 않아요.","2 × 3 = 6 — 왼쪽으로 6 cm예요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[126,36,"e"],"ㄴ":[90,36,"w"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 한 칸이 2 cm예요. 점 ㄱ을 점 ㄴ의 자리로 옮기려면 어떻게 옮겨야 하나요?","options":[{"t":"아래쪽으로 6 cm","correct":true},{"t":"아래쪽으로 3 cm","mis":"M4-2-u6-X04"},{"t":"아래쪽으로 8 cm","mis":"M4-2-u6-X03"},{"t":"위쪽으로 6 cm","mis":"M4-2-u6-X02"}],"explanation":["먼저 칸 수를 세면 3칸이에요.","한 칸이 2 cm라서 칸 수와 cm는 같지 않아요.","3 × 2 = 6 — 아래쪽으로 6 cm예요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[144,18,"n"],"ㄴ":[144,72,"s"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#9','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C1',4,'mc','auto','로니가 점 ㄱ에서 출발해 오른쪽으로 3칸, 위쪽으로 2칸, 왼쪽으로 2칸 옮겼어요. 로니가 도착한 점은 어느 것인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X07','M4-2-u6-X02']::text[],true,'{"seq":9,"concept":"M4-2-u6-C1","difficulty":4,"kind":"mc","stem":"로니가 점 ㄱ에서 출발해 오른쪽으로 3칸, 위쪽으로 2칸, 왼쪽으로 2칸 옮겼어요. 로니가 도착한 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄴ","mis":"M4-2-u6-X06"},{"t":"점 ㄹ","mis":"M4-2-u6-X07"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"}],"explanation":["하나씩 차례로 옮겨요: 오른쪽으로 3칸, 위쪽으로 2칸, 왼쪽으로 2칸.","오른쪽과 왼쪽은 반대 방향이라 가로로는 3 − 2 = 1칸만 남아요.","도착한 점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[36,72,"w"],"ㄴ":[36,18,"nw"],"ㄷ":[54,108,"s"],"ㄹ":[126,36,"e"],"ㅁ":[54,36,"se"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"로니가 점 ㄱ에서 출발해 오른쪽으로 2칸, 위쪽으로 1칸, 왼쪽으로 1칸 옮겼어요. 로니가 도착한 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄴ","mis":"M4-2-u6-X07"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"}],"explanation":["하나씩 차례로 옮겨요: 오른쪽으로 2칸, 위쪽으로 1칸, 왼쪽으로 1칸.","오른쪽과 왼쪽은 반대 방향이라 가로로는 2 − 1 = 1칸만 남아요.","도착한 점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[108,54,"w"],"ㄴ":[162,36,"e"],"ㄷ":[126,72,"se"],"ㄹ":[108,18,"nw"],"ㅁ":[126,36,"ne"]}}],"tag":false}},{"stem":"로니가 점 ㄱ에서 출발해 오른쪽으로 2칸, 위쪽으로 1칸, 왼쪽으로 1칸 옮겼어요. 로니가 도착한 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㅁ","mis":"M4-2-u6-X07"},{"t":"점 ㄴ","mis":"M4-2-u6-X02"}],"explanation":["하나씩 차례로 옮겨요: 오른쪽으로 2칸, 위쪽으로 1칸, 왼쪽으로 1칸.","오른쪽과 왼쪽은 반대 방향이라 가로로는 2 − 1 = 1칸만 남아요.","도착한 점은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[18,72,"w"],"ㄴ":[36,90,"se"],"ㄷ":[36,54,"ne"],"ㄹ":[18,36,"nw"],"ㅁ":[72,54,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L02_challenge#10','math',4,2,'u6','L02','g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',4,'essay','teacher','로니에게 점 ㄱ을 점 ㄴ의 자리로 옮기는 방법을 설명하려고 해요. 점 ㄴ은 점 ㄱ보다 오른쪽으로 5칸, 아래쪽으로 4칸에 있어요. 로니가 알아들을 수 있게 두 가지 방법으로 설명하고, 두 설명이 모두 맞는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C2","difficulty":4,"kind":"essay","stem":"로니에게 점 ㄱ을 점 ㄴ의 자리로 옮기는 방법을 설명하려고 해요. 점 ㄴ은 점 ㄱ보다 오른쪽으로 5칸, 아래쪽으로 4칸에 있어요. 로니가 알아들을 수 있게 두 가지 방법으로 설명하고, 두 설명이 모두 맞는 까닭을 써 보세요.","answer_guide":{"answer":"예: ① 오른쪽으로 5칸 옮기고 아래쪽으로 4칸 옮겨. ② 아래쪽으로 4칸 옮기고 오른쪽으로 5칸 옮겨. 두 방향으로 옮길 때는 말하는 순서를 바꾸어도 도착하는 자리가 같으므로 두 설명이 모두 맞다.","scoring_points":["방향과 칸 수를 함께 말했는가","순서를 바꾼 두 가지로 썼는가","순서를 바꾸어도 도착이 같다고 까닭을 썼는가"]},"explanation":["방향만, 칸 수만 말하면 로니가 움직일 수 없어요.","오른쪽 5칸 → 아래쪽 4칸, 또는 아래쪽 4칸 → 오른쪽 5칸.","순서를 바꾸어도 도착하는 자리는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_basic#1','math',4,2,'u6','L03','g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'mc','auto','평면도형을 밀면 무엇이 변하나요?',ARRAY['M4-2-u6-X08']::text[],true,'{"seq":1,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"평면도형을 밀면 무엇이 변하나요?","options":[{"t":"자리만 변하고 모양은 그대로예요","correct":true},{"t":"모양이 변해요","mis":"M4-2-u6-X08"},{"t":"모양과 크기가 모두 변해요","mis":"M4-2-u6-X08"},{"t":"변하는 것이 없어요","mis":"M4-2-u6-X08"}],"explanation":["도형을 밀면 도형 자체는 하나도 달라지지 않아요.","모양·크기·방향은 그대로이고 자리만 옮겨져요.","밀기를 말할 때는 방향과 칸 수를 함께 말해요."],"variant_rule":{"alt":[{"stem":"배 모양을 오른쪽으로 밀었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"배 모양은 그대로이고 자리만 오른쪽으로 옮겨졌어요","correct":true},{"t":"배가 오른쪽을 보도록 방향이 바뀌었어요","mis":"M4-2-u6-X08"},{"t":"배가 더 커졌어요","mis":"M4-2-u6-X08"},{"t":"배가 뒤집혔어요","mis":"M4-2-u6-X08"}],"explanation":["도형을 밀면 도형 자체는 하나도 달라지지 않아요.","모양·크기·방향은 그대로이고 자리만 옮겨져요.","밀기를 말할 때는 방향과 칸 수를 함께 말해요."],"asset":null},{"stem":"도형을 아래쪽으로 밀었을 때 변하지 않는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"모양, 크기, 방향","correct":true},{"t":"모양만","mis":"M4-2-u6-X08"},{"t":"자리, 모양","mis":"M4-2-u6-X08"},{"t":"아무것도 변하지 않음","mis":"M4-2-u6-X08"}],"explanation":["도형을 밀면 도형 자체는 하나도 달라지지 않아요.","모양·크기·방향은 그대로이고 자리만 옮겨져요.","밀기를 말할 때는 방향과 칸 수를 함께 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_basic#2','math',4,2,'u6','L03','g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'mc','auto','밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X02']::text[],true,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"오른쪽으로 밀었어요","correct":true},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 오른쪽에 있어요.","오른쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":216,"h":72,"grid":18,"poly":[[[144.0,18.0],[198.0,18.0],[144.0,54.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 밀었어요","correct":true},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 아래쪽에 있어요.","아래쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":90,"h":180,"grid":18,"poly":[[[18.0,108.0],[72.0,108.0],[72.0,126.0],[36.0,162.0],[18.0,144.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,72.0]],[[36.0,72.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"위쪽으로 밀었어요","correct":true},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 위쪽에 있어요.","위쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":72,"h":180,"grid":18,"poly":[[[18.0,18.0],[18.0,72.0],[54.0,72.0],[54.0,54.0],[36.0,54.0],[36.0,18.0]]],"dash":[[[18.0,108.0],[18.0,162.0]],[[18.0,162.0],[54.0,162.0]],[[54.0,162.0],[54.0,144.0]],[[54.0,144.0],[36.0,144.0]],[[36.0,144.0],[36.0,108.0]],[[36.0,108.0],[18.0,108.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_basic#3','math',4,2,'u6','L03','g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C4',1,'sa','auto','삼각형을 오른쪽으로 7칸 밀었어요. 왼쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u6-C4","difficulty":1,"kind":"sa","stem":"삼각형을 오른쪽으로 7칸 밀었어요. 왼쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["7"],"explanation":["오른쪽과 왼쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","왼쪽으로 7칸 밀면 처음 자리예요."],"variant_rule":{"alt":[{"stem":"삼각형을 아래쪽으로 5칸 밀었어요. 위쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["5"],"explanation":["아래쪽과 위쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","위쪽으로 5칸 밀면 처음 자리예요."],"asset":null},{"stem":"삼각형을 왼쪽으로 6칸 밀었어요. 오른쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["6"],"explanation":["왼쪽과 오른쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","오른쪽으로 6칸 밀면 처음 자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_basic#4','math',4,2,'u6','L03','g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'ox','auto','도형을 오른쪽으로 밀면 민 후의 도형은 밀기 전의 도형과 모양과 크기가 같아요.',ARRAY['M4-2-u6-X08']::text[],true,'{"seq":4,"concept":"M4-2-u6-C3","difficulty":1,"kind":"ox","stem":"도형을 오른쪽으로 밀면 민 후의 도형은 밀기 전의 도형과 모양과 크기가 같아요.","answer":"O","reason_options":[{"t":"밀면 자리만 바뀌어서","correct":true},{"t":"밀면 모양이 조금씩 바뀌어서","mis":"M4-2-u6-X08"}],"mis":"M4-2-u6-X08","explanation":["밀기는 도형을 미끄러지듯 옮기는 거예요.","모양·크기·방향은 그대로예요.","자리만 바뀌고, 모든 점이 같은 칸 수만큼 옮겨져요."],"variant_rule":{"alt":[{"stem":"도형을 위쪽으로 밀면 도형의 위쪽과 아래쪽이 서로 바뀌어요.","answer":"X","reason_options":[{"t":"밀기는 방향을 바꾸지 않아서","correct":true},{"t":"위쪽으로 밀면 위아래가 바뀌어서","mis":"M4-2-u6-X08"}],"explanation":["밀기는 도형을 미끄러지듯 옮기는 거예요.","모양·크기·방향은 그대로예요.","자리만 바뀌고, 모든 점이 같은 칸 수만큼 옮겨져요."],"asset":null},{"stem":"도형을 아래쪽으로 3칸 밀면 도형의 모든 꼭짓점이 아래쪽으로 3칸씩 옮겨져요.","answer":"O","reason_options":[{"t":"도형 전체가 같은 방향·같은 칸 수로 옮겨져서","correct":true},{"t":"꼭짓점마다 옮겨지는 칸 수가 달라서","mis":"M4-2-u6-X09"}],"explanation":["밀기는 도형을 미끄러지듯 옮기는 거예요.","모양·크기·방향은 그대로예요.","자리만 바뀌고, 모든 점이 같은 칸 수만큼 옮겨져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_basic#5','math',4,2,'u6','L03','g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C4',2,'sa','auto','도형을 오른쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)','{}'::text[],true,'{"seq":5,"concept":"M4-2-u6-C4","difficulty":2,"kind":"sa","stem":"도형을 오른쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","answer":["4"],"explanation":["밀기 전과 민 후에서 같은 꼭짓점 하나를 골라요.","그 꼭짓점이 옮겨진 칸 수를 세요 — 두 도형 사이의 빈칸만 세면 안 돼요.","오른쪽으로 4칸 밀었어요."],"asset":{"type":"geo","items":[{"w":162,"h":72,"grid":18,"poly":[[[90.0,18.0],[144.0,18.0],[90.0,54.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","answer":["5"],"explanation":["밀기 전과 민 후에서 같은 꼭짓점 하나를 골라요.","그 꼭짓점이 옮겨진 칸 수를 세요 — 두 도형 사이의 빈칸만 세면 안 돼요.","왼쪽으로 5칸 밀었어요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,54.0]]],"dash":[[[108.0,18.0],[162.0,18.0]],[[162.0,18.0],[162.0,36.0]],[[162.0,36.0],[126.0,72.0]],[[126.0,72.0],[108.0,54.0]],[[108.0,54.0],[108.0,18.0]]]}],"tag":false}},{"stem":"도형을 아래쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","answer":["7"],"explanation":["밀기 전과 민 후에서 같은 꼭짓점 하나를 골라요.","그 꼭짓점이 옮겨진 칸 수를 세요 — 두 도형 사이의 빈칸만 세면 안 돼요.","아래쪽으로 7칸 밀었어요."],"asset":{"type":"geo","items":[{"w":72,"h":216,"grid":18,"poly":[[[18.0,144.0],[18.0,198.0],[54.0,198.0],[54.0,180.0],[36.0,180.0],[36.0,144.0]]],"dash":[[[18.0,18.0],[18.0,72.0]],[[18.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,54.0]],[[54.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,18.0]],[[36.0,18.0],[18.0,18.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, gradi