INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#3','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'error','auto','도형을 민 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X09','M4-2-u6-X21']::text[],true,'{"seq":3,"concept":"M4-2-u6-C4","difficulty":3,"kind":"error","stem":"도형을 민 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"지아 — 「오른쪽으로 3칸 밀었어.」","correct":true,"mis_target":"M4-2-u6-X09"},{"t":"준서 — 「오른쪽으로 6칸 밀었어.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「모양과 방향은 그대로야.」","mis":"M4-2-u6-X21"},{"t":"도윤 — 「같은 꼭짓점끼리 세면 6칸이야.」","mis":"M4-2-u6-X21"}],"explanation":["민 칸 수는 같은 꼭짓점끼리 세요.","두 도형 사이의 빈칸은 3칸이지만 민 칸 수는 6칸이에요.","지아는 사이 빈칸만 세었어요."],"asset":{"type":"geo","items":[{"w":198,"h":72,"grid":18,"poly":[[[126.0,18.0],[180.0,18.0],[126.0,54.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 도형을 민 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"준서 — 「아래쪽으로 2칸 밀었어.」","correct":true,"mis_target":"M4-2-u6-X09"},{"t":"민서 — 「아래쪽으로 5칸 밀었어.」","mis":"M4-2-u6-X21"},{"t":"도윤 — 「모양과 방향은 그대로야.」","mis":"M4-2-u6-X21"},{"t":"하윤 — 「같은 꼭짓점끼리 세면 5칸이야.」","mis":"M4-2-u6-X21"}],"explanation":["민 칸 수는 같은 꼭짓점끼리 세요.","두 도형 사이의 빈칸은 2칸이지만 민 칸 수는 5칸이에요.","준서는 사이 빈칸만 세었어요."],"asset":{"type":"geo","items":[{"w":90,"h":180,"grid":18,"poly":[[[18.0,108.0],[72.0,108.0],[72.0,126.0],[36.0,162.0],[18.0,144.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,72.0]],[[36.0,72.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 도형을 민 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"민서 — 「왼쪽으로 3칸 밀었어.」","correct":true,"mis_target":"M4-2-u6-X09"},{"t":"도윤 — 「왼쪽으로 5칸 밀었어.」","mis":"M4-2-u6-X21"},{"t":"하윤 — 「모양과 방향은 그대로야.」","mis":"M4-2-u6-X21"},{"t":"동연 — 「같은 꼭짓점끼리 세면 5칸이야.」","mis":"M4-2-u6-X21"}],"explanation":["민 칸 수는 같은 꼭짓점끼리 세요.","두 도형 사이의 빈칸은 3칸이지만 민 칸 수는 5칸이에요.","민서는 사이 빈칸만 세었어요."],"asset":{"type":"geo","items":[{"w":162,"h":90,"grid":18,"poly":[[[18.0,18.0],[18.0,72.0],[54.0,72.0],[54.0,54.0],[36.0,54.0],[36.0,18.0]]],"dash":[[[108.0,18.0],[108.0,72.0]],[[108.0,72.0],[144.0,72.0]],[[144.0,72.0],[144.0,54.0]],[[144.0,54.0],[126.0,54.0]],[[126.0,54.0],[126.0,18.0]],[[126.0,18.0],[108.0,18.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#4','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C3',3,'sa','auto','자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 나 자동차를 아래쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u6-C3","difficulty":3,"kind":"sa","stem":"자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 나 자동차를 아래쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["가 자동차가 지나갈 줄에서 나 자동차를 비켜야 해요.","나 자동차가 그 줄을 완전히 벗어날 때까지 아래쪽으로 한 칸씩 밀어 봐요.","적어도 2칸 밀어야 해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,56.16],[33.84,56.16],[33.84,69.84],[2.16,69.84]],[[38.16,38.16],[51.84,38.16],[51.84,69.84],[38.16,69.84]]],"lab":[[[18.0,63.0],"가"],[[45.0,54.0],"나"],[[117.9,63.0],"출구"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 나 자동차를 위쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["가 자동차가 지나갈 줄에서 나 자동차를 비켜야 해요.","나 자동차가 그 줄을 완전히 벗어날 때까지 위쪽으로 한 칸씩 밀어 봐요.","적어도 2칸 밀어야 해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,74.16],[33.84,74.16],[33.84,87.84],[2.16,87.84]],[[56.16,56.16],[69.84,56.16],[69.84,105.84],[56.16,105.84]]],"lab":[[[18.0,81.0],"가"],[[63.0,81.0],"나"],[[117.9,81.0],"출구"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 나 자동차를 아래쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["가 자동차가 지나갈 줄에서 나 자동차를 비켜야 해요.","나 자동차가 그 줄을 완전히 벗어날 때까지 아래쪽으로 한 칸씩 밀어 봐요.","적어도 1칸 밀어야 해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,20.16],[33.84,20.16],[33.84,33.84],[2.16,33.84]],[[38.16,20.16],[51.84,20.16],[51.84,69.84],[38.16,69.84]]],"lab":[[[18.0,27.0],"가"],[[45.0,45.0],"나"],[[117.9,27.0],"출구"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, diff