INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#5','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'sa','auto','꼭짓점 ㄱ이 점 ㄴ에 오도록 도형을 밀려고 해요. 가로와 세로로만 민다면 모두 몇 칸 밀어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u6-C4","difficulty":3,"kind":"sa","stem":"꼭짓점 ㄱ이 점 ㄴ에 오도록 도형을 밀려고 해요. 가로와 세로로만 민다면 모두 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["꼭짓점 ㄱ에서 점 ㄴ까지 가로로 오른쪽으로 5칸, 세로로 아래쪽으로 1칸이에요.","도형 전체가 같은 칸 수만큼 밀려요.","5 + 1 = 6칸이에요."],"asset":{"type":"geo","items":[{"w":216,"h":144,"grid":18,"poly":[[[36.0,72.0],[90.0,72.0],[36.0,108.0]]],"pts":{"ㄱ":[90.0,72.0,"nw"],"ㄴ":[180.0,90.0,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭짓점 ㄱ이 점 ㄴ에 오도록 도형을 밀려고 해요. 위쪽으로 1칸 민 다음 오른쪽으로 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["꼭짓점 ㄱ에서 점 ㄴ까지 가로로 오른쪽으로 4칸, 세로로 위쪽으로 1칸이에요.","세로는 이미 밀었으니 가로만 남았어요.","4칸 밀어야 해요."],"asset":{"type":"geo","items":[{"w":216,"h":144,"grid":18,"poly":[[[18.0,36.0],[72.0,54.0],[36.0,72.0],[36.0,108.0],[18.0,108.0]]],"pts":{"ㄱ":[18.0,36.0,"w"],"ㄴ":[90.0,18.0,"e"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 꼭짓점 ㄱ이 점 ㄴ에 오도록 도형을 밀려고 해요. 가로와 세로로만 민다면 모두 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["꼭짓점 ㄱ에서 점 ㄴ까지 가로로 오른쪽으로 4칸, 세로로 위쪽으로 1칸이에요.","도형 전체가 같은 칸 수만큼 밀려요.","4 + 1 = 5칸이에요."],"asset":{"type":"geo","items":[{"w":216,"h":144,"grid":18,"poly":[[[18.0,36.0],[18.0,90.0],[54.0,90.0],[54.0,72.0],[36.0,72.0],[36.0,36.0]]],"pts":{"ㄱ":[54.0,90.0,"sw"],"ㄴ":[126.0,72.0,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#6','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'mc','auto','도형을 차례로 밀었을 때 처음 자리로 돌아오는 것은 어느 것인가요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X03']::text[],true,'{"seq":6,"concept":"M4-2-u6-C4","difficulty":3,"kind":"mc","stem":"도형을 차례로 밀었을 때 처음 자리로 돌아오는 것은 어느 것인가요?","options":[{"t":"오른쪽으로 2칸, 위쪽으로 3칸, 왼쪽으로 2칸, 아래쪽으로 3칸 밀기","correct":true},{"t":"오른쪽으로 2칸, 위쪽으로 3칸, 오른쪽으로 2칸, 위쪽으로 3칸 밀기","mis":"M4-2-u6-X07"},{"t":"오른쪽으로 2칸, 위쪽으로 3칸, 왼쪽으로 3칸, 아래쪽으로 2칸 밀기","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 2칸, 위쪽으로 3칸, 왼쪽으로 3칸, 아래쪽으로 3칸 밀기","mis":"M4-2-u6-X03"}],"explanation":["가로와 세로를 따로 생각해요.","오른쪽과 왼쪽은 같은 칸 수, 위쪽과 아래쪽도 같은 칸 수여야 해요.","두 방향 모두 되돌아온 것을 골라요."],"variant_rule":{"alt":[{"stem":"도형을 차례로 밀었을 때 처음 자리로 돌아오는 것은 어느 것인가요?","options":[{"t":"왼쪽으로 5칸, 위쪽으로 4칸, 오른쪽으로 5칸, 아래쪽으로 4칸 밀기","correct":true},{"t":"왼쪽으로 5칸, 위쪽으로 4칸, 왼쪽으로 5칸, 위쪽으로 4칸 밀기","mis":"M4-2-u6-X07"},{"t":"왼쪽으로 5칸, 위쪽으로 4칸, 오른쪽으로 4칸, 아래쪽으로 5칸 밀기","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 5칸, 위쪽으로 4칸, 오른쪽으로 6칸, 아래쪽으로 4칸 밀기","mis":"M4-2-u6-X03"}],"explanation":["가로와 세로를 따로 생각해요.","왼쪽과 오른쪽은 같은 칸 수, 위쪽과 아래쪽도 같은 칸 수여야 해요.","두 방향 모두 되돌아온 것을 골라요."],"asset":null},{"stem":"도형을 차례로 밀었을 때 처음 자리로 돌아오는 것은 어느 것인가요?","options":[{"t":"오른쪽으로 3칸, 아래쪽으로 2칸, 왼쪽으로 3칸, 위쪽으로 2칸 밀기","correct":true},{"t":"오른쪽으로 3칸, 아래쪽으로 2칸, 오른쪽으로 3칸, 아래쪽으로 2칸 밀기","mis":"M4-2-u6-X07"},{"t":"오른쪽으로 3칸, 아래쪽으로 2칸, 왼쪽으로 2칸, 위쪽으로 3칸 밀기","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 3칸, 아래쪽으로 2칸, 왼쪽으로 4칸, 위쪽으로 2칸 밀기","mis":"M4-2-u6-X03"}],"explanation":["가로와 세로를 따로 생각해요.","오른쪽과 왼쪽은 같은 칸 수, 아래쪽과 위쪽도 같은 칸 수여야 해요.","두 방향 모두 되돌아온 것을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconc