,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"위쪽으로 2칸 밀고 왼쪽으로 5칸 밀었어요","correct":true},{"t":"왼쪽으로 2칸 밀고 위쪽으로 5칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 5칸 밀고 위쪽으로 2칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 6칸 밀고 위쪽으로 2칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 왼쪽으로 5칸, 세로로 위쪽으로 2칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,18.0],[36.0,18.0]]],"dash":[[[126.0,72.0],[108.0,72.0]],[[108.0,72.0],[108.0,90.0]],[[108.0,90.0],[126.0,90.0]],[[126.0,90.0],[126.0,108.0]],[[126.0,108.0],[144.0,108.0]],[[144.0,108.0],[144.0,72.0]],[[144.0,72.0],[162.0,72.0]],[[162.0,72.0],[162.0,54.0]],[[162.0,54.0],[126.0,54.0]],[[126.0,54.0],[126.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#8','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C3',4,'mc','auto','자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 어떻게 밀어야 하나요? (자동차는 길쭉한 방향으로만 움직여요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03','M4-2-u6-X01']::text[],true,'{"seq":8,"concept":"M4-2-u6-C3","difficulty":4,"kind":"mc","stem":"자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 어떻게 밀어야 하나요? (자동차는 길쭉한 방향으로만 움직여요.)","options":[{"t":"다 자동차를 왼쪽으로 2칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","correct":true},{"t":"다 자동차를 오른쪽으로 2칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","mis":"M4-2-u6-X02"},{"t":"다 자동차를 왼쪽으로 2칸 밀고, 나 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X03"},{"t":"나 자동차를 위쪽으로 3칸 밀어요","mis":"M4-2-u6-X01"}],"explanation":["나 자동차는 위쪽이 막혀 아래쪽으로만 비킬 수 있는데, 그 아래를 다 자동차가 막고 있어요.","다 자동차를 왼쪽으로 2칸 밀어 길을 연 다음, 나 자동차를 아래쪽으로 3칸 밀어요.","어떤 차를 어느 쪽으로 몇 칸 미는지 차례대로 말해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,38.16],[33.84,38.16],[33.84,51.84],[2.16,51.84]],[[56.16,2.16],[69.84,2.16],[69.84,51.84],[56.16,51.84]],[[56.16,56.16],[87.84,56.16],[87.84,69.84],[56.16,69.84]],[[92.16,74.16],[105.84,74.16],[105.84,105.84],[92.16,105.84]]],"lab":[[[18.0,45.0],"가"],[[63.0,27.0],"나"],[[72.0,63.0],"다"],[[99.0,90.0],"라"],[[117.9,45.0],"출구"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 어떻게 밀어야 하나요? (자동차는 길쭉한 방향으로만 움직여요.)","options":[{"t":"다 자동차를 왼쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","correct":true},{"t":"다 자동차를 오른쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","mis":"M4-2-u6-X02"},{"t":"다 자동차를 왼쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X03"},{"t":"나 자동차를 위쪽으로 3칸 밀어요","mis":"M4-2-u6-X01"}],"explanation":["나 자동차는 위쪽이 막혀 아래쪽으로만 비킬 수 있는데, 그 아래를 다 자동차가 막고 있어요.","다 자동차를 왼쪽으로 1칸 밀어 길을 연 다음, 나 자동차를 아래쪽으로 3칸 밀어요.","어떤 차를 어느 쪽으로 몇 칸 미는지 차례대로 말해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,38.16],[33.84,38.16],[33.84,51.84],[2.16,51.84]],[[38.16,2.16],[51.84,2.16],[51.84,51.84],[38.16,51.84]],[[20.16,56.16],[51.84,56.16],[51.84,69.84],[20.16,69.84]],[[2.16,74.16],[15.84,74.16],[15.84,105.84],[2.16,105.84]]],"lab":[[[18.0,45.0],"가"],[[45.0,27.0],"나"],[[36.0,63.0],"다"],[[9.0,90.0],"라"],[[117.9,45.0],"출구"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 자동차 탈출 놀이예요. 가 자동차를 오른쪽 출구로 내보내려면 어떻게 밀어야 하나요? (자동차는 길쭉한 방향으로만 움직여요.)","options":[{"t":"다 자동차를 오른쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","correct":true},{"t":"다 자동차를 왼쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 3칸 밀어요","mis":"M4-2-u6-X02"},{"t":"다 자동차를 오른쪽으로 1칸 밀고, 나 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X03"},{"t":"나 자동차를 위쪽으로 3칸 밀어요","mis":"M4-2-u6-X01"}],"explanation":["나 자동차는 위쪽이 막혀 아래쪽으로만 비킬 수 있는데, 그 아래를 다 자동차가 막고 있어요.","다 자동차를 오른쪽으로 1칸 밀어 길을 연 다음, 나 자동차를 아래쪽으로 3칸 밀어요.","어떤 차를 어느 쪽으로 몇 칸 미는지 차례대로 말해요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[2.16,38.16],[33.84,38.16],[33.84,51.84],[2.16,51.84]],[[56.16,2.16],[69.84,2.16],[69.84,51.84],[56.16,51.84]],[[56.16,56.16],[87.84,56.16],[87.84,69.84],[56.16,69.84]],[[92.16,74.16],[105.84,74.16],[105.84,105.84],[92.16,105.84]]],"lab":[[[18.0,45.0],"가"],[[63.0,27.0],"나"],[[72.0,63.0],"다"],[[99.0,90.0],"라"],[[117.9,45.0],"출구"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#9','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',4,'sa','auto','도형을 오른쪽으로 4칸, 아래쪽으로 6칸, 왼쪽으로 1칸, 위쪽으로 3칸 밀었어요. 이 도형을 가로와 세로로만 밀어 처음 자리로 되돌리려면 모두 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u6-C4","difficulty":4,"kind":"sa","stem":"도형을 오른쪽으로 4칸, 아래쪽으로 6칸, 왼쪽으로 1칸, 위쪽으로 3칸 밀었어요. 이 도형을 가로와 세로로만 밀어 처음 자리로 되돌리려면 모두 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["가로: 오른쪽 4칸, 왼쪽 1칸 → 처음보다 오른쪽으로 3칸.","세로: 아래쪽 6칸, 위쪽 3칸 → 처음보다 아래쪽으로 3칸.","되돌리려면 그 반대로 3 + 3 = 6칸이에요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 5칸, 아래쪽으로 4칸, 오른쪽으로 4칸, 위쪽으로 3칸 밀었어요. 이 도형을 가로와 세로로만 밀어 처음 자리로 되돌리려면 모두 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["가로: 왼쪽 5칸, 오른쪽 4칸 → 처음보다 왼쪽으로 1칸.","세로: 아래쪽 4칸, 위쪽 3칸 → 처음보다 아래쪽으로 1칸.","되돌리려면 그 반대로 1 + 1 = 2칸이에요."],"asset":null},{"stem":"도형을 오른쪽으로 6칸, 위쪽으로 2칸, 왼쪽으로 4칸, 아래쪽으로 4칸 밀었어요. 이 도형을 가로와 세로로만 밀어 처음 자리로 되돌리려면 모두 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로: 오른쪽 6칸, 왼쪽 4칸 → 처음보다 오른쪽으로 2칸.","세로: 위쪽 2칸, 아래쪽 4칸 → 처음보다 아래쪽으로 2칸.","되돌리려면 그 반대로 2 + 2 = 4칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L03_challenge#10','math',4,2,'u6','L03','g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',4,'essay','teacher','사각형을 밀었더니 밀기 전과 민 후의 두 사각형 사이에 빈칸이 2칸 있었어요. 사각형의 가로는 3칸이에요. 한 친구가 「오른쪽으로 2칸 밀었어.」라고 했어요. 친구가 무엇을 잘못했는지 쓰고, 바르게 몇 칸 밀었는지와 민 칸 수를 세는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C4","difficulty":4,"kind":"essay","stem":"사각형을 밀었더니 밀기 전과 민 후의 두 사각형 사이에 빈칸이 2칸 있었어요. 사각형의 가로는 3칸이에요. 한 친구가 「오른쪽으로 2칸 밀었어.」라고 했어요. 친구가 무엇을 잘못했는지 쓰고, 바르게 몇 칸 밀었는지와 민 칸 수를 세는 방법을 써 보세요.","answer_guide":{"answer":"예: 친구는 두 사각형 사이의 빈칸만 세었다. 민 칸 수는 밀기 전과 민 후의 같은 꼭짓점끼리 세어야 한다. 사각형의 가로 3칸과 빈칸 2칸을 더하면 같은 꼭짓점끼리 5칸 떨어져 있으므로 오른쪽으로 5칸 밀었다.","scoring_points":["사이 빈칸만 센 잘못을 썼는가","같은 꼭짓점끼리 센다고 썼는가","오른쪽으로 5칸이라고 구했는가"]},"explanation":["두 도형 사이 빈칸은 민 칸 수가 아니에요.","같은 꼭짓점끼리 세요.","3 + 2 = 5 — 오른쪽으로 5칸 밀었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#1','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',1,'mc','auto','평면도형을 뒤집으면 무엇이 변하나요?',ARRAY['M4-2-u6-X11']::text[],true,'{"seq":1,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"평면도형을 뒤집으면 무엇이 변하나요?","options":[{"t":"방향","correct":true},{"t":"모양","mis":"M4-2-u6-X11"},{"t":"크기","mis":"M4-2-u6-X11"},{"t":"개수","mis":"M4-2-u6-X11"}],"explanation":["뒤집어도 도형 자체의 모양과 크기는 그대로예요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","그래서 뒤집으면 방향이 변해요."],"variant_rule":{"alt":[{"stem":"깃발 모양을 오른쪽으로 뒤집었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"모양은 그대로이고 왼쪽과 오른쪽이 서로 바뀌었어요","correct":true},{"t":"모양이 달라졌어요","mis":"M4-2-u6-X11"},{"t":"위쪽과 아래쪽이 서로 바뀌었어요","mis":"M4-2-u6-X10"},{"t":"자리만 옮겨지고 그대로예요","mis":"M4-2-u6-X11"}],"explanation":["뒤집어도 도형 자체의 모양과 크기는 그대로예요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","그래서 뒤집으면 방향이 변해요."],"asset":null},{"stem":"도형을 아래쪽으로 뒤집었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"모양은 그대로이고 위쪽과 아래쪽이 서로 바뀌었어요","correct":true},{"t":"왼쪽과 오른쪽이 서로 바뀌었어요","mis":"M4-2-u6-X10"},{"t":"도형이 더 작아졌어요","mis":"M4-2-u6-X11"},{"t":"아무것도 변하지 않았어요","mis":"M4-2-u6-X11"}],"explanation":["뒤집어도 도형 자체의 모양과 크기는 그대로예요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","그래서 뒤집으면 방향이 변해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#2','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',1,'mc','auto','사각형을 위쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X11']::text[],true,'{"seq":2,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"사각형을 위쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"아래쪽으로 뒤집기","correct":true},{"t":"왼쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"오른쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"위쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"오른쪽으로 뒤집기","correct":true},{"t":"위쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"왼쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null},{"stem":"삼각형을 아래쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"위쪽으로 뒤집기","correct":true},{"t":"오른쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"왼쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"아래쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#3','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',1,'mc','auto','도형을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],true,'{"seq":3,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"도형을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"왼쪽과 오른쪽","correct":true},{"t":"위쪽과 아래쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"variant_rule":{"alt":[{"stem":"도형을 위쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"위쪽과 아래쪽","correct":true},{"t":"왼쪽과 오른쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null},{"stem":"도형의 왼쪽에 있던 부분이 오른쪽으로 갔어요. 어떻게 뒤집은 것인가요?","options":[{"t":"왼쪽이나 오른쪽으로 뒤집었어요","correct":true},{"t":"위쪽이나 아래쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X11"},{"t":"크기를 바꾸었어요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#4','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',1,'mc','auto','교실 밖에서 「4-3」으로 보이게 창문에 쓰려면 교실 안에서 어떻게 써야 하나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X14','M4-2-u6-X11']::text[],true,'{"seq":4,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"교실 밖에서 「4-3」으로 보이게 창문에 쓰려면 교실 안에서 어떻게 써야 하나요?","options":[{"t":"왼쪽이나 오른쪽으로 뒤집어 써요","correct":true},{"t":"위쪽으로 뒤집어 써요","mis":"M4-2-u6-X10"},{"t":"그대로 써요","mis":"M4-2-u6-X14"},{"t":"글자를 더 크게 써요","mis":"M4-2-u6-X11"}],"explanation":["창문 너머나 거울, 도장으로 찍힌 글자는 왼쪽과 오른쪽이 서로 바뀌어요.","그래서 미리 왼쪽이나 오른쪽으로 뒤집어 써 두면 바르게 보여요.","글자의 순서까지 통째로 바뀌어요."],"variant_rule":{"alt":[{"stem":"교실 안에서 창문에 「4-3」을 그대로 썼어요. 교실 밖에서는 어떻게 보이나요?","options":[{"t":"왼쪽과 오른쪽이 서로 바뀌어 보여요","correct":true},{"t":"위쪽과 아래쪽이 서로 바뀌어 보여요","mis":"M4-2-u6-X10"},{"t":"그대로 「4-3」으로 보여요","mis":"M4-2-u6-X14"},{"t":"글자가 커 보여요","mis":"M4-2-u6-X11"}],"explanation":["창문 너머나 거울, 도장으로 찍힌 글자는 왼쪽과 오른쪽이 서로 바뀌어요.","그래서 미리 왼쪽이나 오른쪽으로 뒤집어 써 두면 바르게 보여요.","글자의 순서까지 통째로 바뀌어요."],"asset":null},{"stem":"도장으로 「오이」가 찍히게 하려면 도장에 글자를 어떻게 새겨야 하나요?","options":[{"t":"글자를 왼쪽이나 오른쪽으로 뒤집어 새겨요","correct":true},{"t":"글자를 그대로 새겨요","mis":"M4-2-u6-X14"},{"t":"글자를 위쪽으로 뒤집어 새겨요","mis":"M4-2-u6-X10"},{"t":"글자를 시계 방향으로 90°만큼 돌려 새겨요","mis":"M4-2-u6-X18"}],"explanation":["창문 너머나 거울, 도장으로 찍힌 글자는 왼쪽과 오른쪽이 서로 바뀌어요.","그래서 미리 왼쪽이나 오른쪽으로 뒤집어 써 두면 바르게 보여요.","글자의 순서까지 통째로 바뀌어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
