INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#6','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',2,'sa','auto','도형을 아래쪽으로 3번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u6-C6","difficulty":2,"kind":"sa","stem":"도형을 아래쪽으로 3번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["1"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","3번은 두 번씩 1묶음과 한 번 더예요.","한 번 뒤집은 것과 같아요 — 1을 써요."],"variant_rule":{"alt":[{"stem":"도형을 위쪽으로 2번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["0"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","2번은 두 번씩 1묶음이에요.","처음 도형과 같아요 — 0을 써요."],"asset":null},{"stem":"도형을 오른쪽으로 5번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["1"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","5번은 두 번씩 2묶음과 한 번 더예요.","한 번 뒤집은 것과 같아요 — 1을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#7','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',2,'mc','auto','점선 도형을 움직였더니 색칠한 도형이 되었어요. 어떻게 움직인 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X18','M4-2-u6-X11']::text[],true,'{"seq":7,"concept":"M4-2-u6-C5","difficulty":2,"kind":"mc","stem":"점선 도형을 움직였더니 색칠한 도형이 되었어요. 어떻게 움직인 것인가요?","options":[{"t":"왼쪽이나 오른쪽으로 뒤집었어요","correct":true},{"t":"위쪽이나 아래쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X18"},{"t":"뒤집지 않고 밀었어요","mis":"M4-2-u6-X11"}],"explanation":["두 도형에서 같은 부분이 어디로 갔는지 봐요.","위아래는 그대로이고 왼쪽과 오른쪽이 서로 바뀌었어요.","왼쪽이나 오른쪽으로 뒤집었어요."],"asset":{"type":"geo","items":[{"w":126,"h":90,"grid":18,"poly":[[[108.0,18.0],[108.0,72.0],[72.0,72.0],[72.0,54.0],[90.0,54.0],[90.0,18.0]]],"dash":[[[18.0,18.0],[18.0,72.0]],[[18.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,54.0]],[[54.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,18.0]],[[36.0,18.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점선 도형을 움직였더니 색칠한 도형이 되었어요. 어떻게 움직인 것인가요?","options":[{"t":"위쪽이나 아래쪽으로 뒤집었어요","correct":true},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X18"},{"t":"뒤집지 않고 밀었어요","mis":"M4-2-u6-X11"}],"explanation":["두 도형에서 같은 부분이 어디로 갔는지 봐요.","좌우는 그대로이고 위쪽과 아래쪽이 서로 바뀌었어요.","위쪽이나 아래쪽으로 뒤집었어요."],"asset":{"type":"geo","items":[{"w":90,"h":126,"grid":18,"poly":[[[18.0,108.0],[54.0,108.0],[72.0,72.0],[18.0,72.0]]],"dash":[[[18.0,18.0],[54.0,18.0]],[[54.0,18.0],[72.0,54.0]],[[72.0,54.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점선 도형을 움직였더니 색칠한 도형이 되었어요. 어떻게 움직인 것인가요?","options":[{"t":"위쪽이나 아래쪽으로 뒤집었어요","correct":true},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X18"},{"t":"뒤집지 않고 밀었어요","mis":"M4-2-u6-X11"}],"expla