INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#9','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',2,'ox','auto','도형을 아래쪽으로 뒤집으면 왼쪽과 오른쪽이 서로 바뀌어요.',ARRAY['M4-2-u6-X10']::text[],true,'{"seq":9,"concept":"M4-2-u6-C6","difficulty":2,"kind":"ox","stem":"도형을 아래쪽으로 뒤집으면 왼쪽과 오른쪽이 서로 바뀌어요.","answer":"X","reason_options":[{"t":"아래쪽으로 뒤집으면 위쪽과 아래쪽이 바뀌어서","correct":true},{"t":"어느 쪽으로 뒤집어도 좌우가 바뀌어서","mis":"M4-2-u6-X10"}],"mis":"M4-2-u6-X10","explanation":["뒤집으면 모양은 그대로이고 방향이 변해요.","위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번이면 처음과 같아요."],"variant_rule":{"alt":[{"stem":"도형을 오른쪽으로 뒤집어도 모양과 크기는 그대로예요.","answer":"O","reason_options":[{"t":"뒤집으면 방향만 변해서","correct":true},{"t":"뒤집으면 모양이 달라져서","mis":"M4-2-u6-X11"}],"explanation":["뒤집으면 모양은 그대로이고 방향이 변해요.","위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번이면 처음과 같아요."],"asset":null},{"stem":"위쪽으로 뒤집은 도형과 아래쪽으로 뒤집은 도형은 서로 같아요.","answer":"O","reason_options":[{"t":"둘 다 위아래를 서로 바꾸어서","correct":true},{"t":"뒤집는 쪽이 달라 결과도 달라서","mis":"M4-2-u6-X12"}],"explanation":["뒤집으면 모양은 그대로이고 방향이 변해요.","위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번이면 처음과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_basic#10','math',4,2,'u6','L04','g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',3,'mc','auto','처음 도형을 오른쪽으로 뒤집은 다음 아래쪽으로 뒤집었어요. 그 결과는 어느 것인가요?',ARRAY['M4-2-u6-X13','M4-2-u6-X10']::text[],true,'{"seq":10,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"처음 도형을 오른쪽으로 뒤집은 다음 아래쪽으로 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X13"},{"t":"㉰","mis":"M4-2-u6-X10"},{"t":"㉱","mis":"M4-2-u6-X10"}],"explanation":["먼저 오른쪽으로 뒤집으면 좌우가 바뀌어요.","이어서 아래쪽으로 뒤집으면 위아래가 바뀌어요 — 좌우와 위아래가 모두 바뀌어요.","서로 다른 쪽으로 두 번 뒤집으면 처음으로 돌아오지 않아요."],"asset":{"type":"geo","items":[{"w":72,"h":108,"grid":18,"poly":[[[54.0,18.0],[36.0,18.0],[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,90.0],[54.0,90.0]]],"cap":"처음 도형"},{"w":72,"h":108,"grid":18,"poly":[[[54.0,18.0],[36.0,18.0],[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,90.0],[54.0,90.0]]],"cap":"㉮"},{"w":72,"h":108,"grid":18,"poly":[[[18.0,90.0],[36.0,90.0],[36.0,72.0],[54.0,72.0],[54.0,54.0],[36.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"㉯"},{"w":72,"h":108,"grid":18,"poly":[[[18.0,18.0],[36.0,18.0],[36.0,36.0],[54.0,36.0],[54.0,54.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"㉰"},{"w":72,"h":108,"grid":18,"poly":[[[54.0,90.0],[36.0,90.0],[36.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,18.0],[54.0,18.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"처음 도형을 오른쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉱","mis":"M4-2-u6-X13"},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["한 번 뒤집으면 좌우가 바뀌어요.","한 번 더 같은 쪽으로 뒤집으면 다시 바뀌어 제자리예요.","같은 쪽으로 두 번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"처음 도형"},{"w":90,"h