INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_challenge#6','math',4,2,'u6','L04','g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',3,'mc','auto','처음 도형을 아래쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?',ARRAY['M4-2-u6-X13','M4-2-u6-X10','M4-2-u6-X18']::text[],true,'{"seq":6,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"처음 도형을 아래쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉰","mis":"M4-2-u6-X13"},{"t":"㉮","mis":"M4-2-u6-X10"},{"t":"㉯","mis":"M4-2-u6-X18"}],"explanation":["한 번 뒤집으면 위아래가 바뀌어요.","한 번 더 같은 쪽으로 뒤집으면 다시 바뀌어 제자리예요.","같은 쪽으로 두 번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":72,"h":90,"grid":18,"poly":[[[18.0,72.0],[36.0,72.0],[36.0,54.0],[54.0,54.0],[54.0,18.0],[18.0,18.0]]],"cap":"처음 도형"},{"w":72,"h":90,"grid":18,"poly":[[[54.0,72.0],[36.0,72.0],[36.0,54.0],[18.0,54.0],[18.0,18.0],[54.0,18.0]]],"cap":"㉮"},{"w":72,"h":90,"grid":18,"poly":[[[54.0,18.0],[36.0,18.0],[36.0,36.0],[18.0,36.0],[18.0,72.0],[54.0,72.0]]],"cap":"㉯"},{"w":72,"h":90,"grid":18,"poly":[[[18.0,18.0],[36.0,18.0],[36.0,36.0],[54.0,36.0],[54.0,72.0],[18.0,72.0]]],"cap":"㉰"},{"w":72,"h":90,"grid":18,"poly":[[[18.0,72.0],[36.0,72.0],[36.0,54.0],[54.0,54.0],[54.0,18.0],[18.0,18.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"처음 도형을 오른쪽으로 뒤집은 다음 아래쪽으로 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉯","mis":"M4-2-u6-X13"},{"t":"㉮","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X10"}],"explanation":["먼저 오른쪽으로 뒤집으면 좌우가 바뀌어요.","이어서 아래쪽으로 뒤집으면 위아래가 바뀌어요 — 좌우와 위아래가 모두 바뀌어요.","서로 다른 쪽으로 두 번 뒤집으면 처음으로 돌아오지 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,54.0],[18.0,54.0]]],"cap":"처음 도형"},{"w":90,"h":72,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,54.0],[72.0,54.0]]],"cap":"㉮"},{"w":90,"h":72,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,54.0],[18.0,54.0]]],"cap":"㉯"},{"w":90,"h":72,"grid":18,"poly":[[[18.0,54.0],[54.0,54.0],[72.0,18.0],[18.0,18.0]]],"cap":"㉰"},{"w":90,"h":72,"grid":18,"poly":[[[72.0,54.0],[36.0,54.0],[18.0,18.0],[72.0,18.0]]],"cap":"㉱"}],"tag":false}},{"stem":"처음 도형을 오른쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X13"},{"t":"㉱","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["한 번 뒤집으면 좌우가 바뀌어요.","한 번 더 같은 쪽으로 뒤집으면 다시 바뀌어 제자리예요.","같은 쪽으로 두 번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[54.0,36.0],[54.0,54.0],[36.0,54.0],[36.0,72.0],[72.0,72.0],[72.0,18.0],[18.0,18.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[36.0,36.0],[36.0,54.0],[54.0,54.0],[54.0,72.0],[18.0,72.0],[18.0,18.0],[72.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[54.0,36.0],[54.0,54.0],[36.0,54.0],[36.0,72.0],[72.0,72.0],[72.0,18.0],[18.0,18.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,54.0],[36.0,54.0],[36.0,36.0],[54.0,36.0],[54.0,18.0],[18.0,18.0],[18.0,72.0],[72.0,72.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[54.0,54.0],[54.0,36.0],[36.0,36.0],[36.0,18.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"㉱"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_challenge#7','math',4,2,'u6','L04','g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',3,'error','auto','뒤집기에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X21']::text[],true,'{"seq":7,"concept":"M4-2-u6-C6","difficulty":3,"kind":"error","stem":"뒤집기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「위쪽으로 뒤집은 것과 아래쪽으로 뒤집은 것은 결과가 달라.」","correct":true,"mis_target":"M4-2-u6-X12"},{"t":"은우 — 「뒤집어도 모양과 크기는 그대로야.」","mis":"M4-2-u6-X21"},{"t":"하랑 — 「왼쪽으로 뒤집기와 오른쪽으로 뒤집기는 결과가 같아.」","mis":"M4-2-u6-X21"},{"t":"지아 — 「아래쪽으로 두 번 뒤집으면 처음 도형과 같아.」","mis":"M4-2-u6-X21"}],"explanation":["위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번 뒤집으면 처음으로 돌아와요.","시우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"뒤집기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「오른쪽으로 두 번 뒤집으면 오른쪽으로 한 번 뒤집은 것과 같아.」","correct":true,"mis_target":"M4-2-u6-X13"},{"t":"하랑 — 「왼쪽으로 뒤집기와 오른쪽으로 뒤집기는 결과가 같아.」","mis":"M4-2-u6-X21"},{"t":"지아 — 「아래쪽으로 두 번 뒤집으면 처음 도형과 같아.」","mis":"M4-2-u6-X21"},{"t":"준서 — 「오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어.」","mis":"M4-2-u6-X21"}],"explanation":["위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번 뒤집으면 처음으로 돌아와요.","은우의 말이 틀렸어요."],"asset":null},{"stem":"뒤집기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「왼쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어.」","correct":true,"mis_target":"M4-2-u6-X10"},{"t":"지아 — 「아래쪽으로 두 번 뒤집으면 처음 도형과 같아.」","mis":"M4-2-u6-X21"},{"t":"준서 — 「오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「「응」은 위쪽으로 뒤집어도 「응」으로 보여.」","mis":"M4-2-u6-X21"}],"explanation":["위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 두 번 뒤집으면 처음으로 돌아와요.","하랑의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUD