INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_challenge#9','math',4,2,'u6','L04','g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',4,'sa','auto','도형을 위쪽으로 7번, 아래쪽으로 2번 뒤집었어요. 처음 도형과 같아지려면 위쪽으로 적어도 몇 번 더 뒤집어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u6-C6","difficulty":4,"kind":"sa","stem":"도형을 위쪽으로 7번, 아래쪽으로 2번 뒤집었어요. 처음 도형과 같아지려면 위쪽으로 적어도 몇 번 더 뒤집어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["위쪽 뒤집기와 아래쪽 뒤집기는 결과가 같아요 — 모두 9번 뒤집은 셈이에요.","두 번 뒤집을 때마다 처음으로 돌아오니 짝수 번이면 처음, 홀수 번이면 한 번 뒤집은 것과 같아요.","9번은 홀 수 — 한 번 더 뒤집으면 돼요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 3번, 오른쪽으로 3번 뒤집었어요. 처음 도형과 같아지려면 왼쪽으로 적어도 몇 번 더 뒤집어야 하나요? 숫자로 쓰세요.","answer":["0"],"explanation":["왼쪽 뒤집기와 오른쪽 뒤집기는 결과가 같아요 — 모두 6번 뒤집은 셈이에요.","두 번 뒤집을 때마다 처음으로 돌아오니 짝수 번이면 처음, 홀수 번이면 한 번 뒤집은 것과 같아요.","6번은 짝 수 — 더 뒤집지 않아도 되어 0번이에요."],"asset":null},{"stem":"도형을 위쪽으로 4번, 아래쪽으로 5번 뒤집었어요. 처음 도형과 같아지려면 위쪽으로 적어도 몇 번 더 뒤집어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["위쪽 뒤집기와 아래쪽 뒤집기는 결과가 같아요 — 모두 9번 뒤집은 셈이에요.","두 번 뒤집을 때마다 처음으로 돌아오니 짝수 번이면 처음, 홀수 번이면 한 번 뒤집은 것과 같아요.","9번은 홀 수 — 한 번 더 뒤집으면 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L04_challenge#10','math',4,2,'u6','L04','g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',4,'essay','teacher','도장으로 「오이」가 찍히게 하려고 해요. 한 친구는 「오」와 「이」를 하나씩 왼쪽·오른쪽으로 뒤집되 「오이」의 순서는 그대로 두어 새겼어요. 이 도장으로 찍으면 어떻게 되는지 쓰고, 바르게 새기는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C6","difficulty":4,"kind":"essay","stem":"도장으로 「오이」가 찍히게 하려고 해요. 한 친구는 「오」와 「이」를 하나씩 왼쪽·오른쪽으로 뒤집되 「오이」의 순서는 그대로 두어 새겼어요. 이 도장으로 찍으면 어떻게 되는지 쓰고, 바르게 새기는 방법을 써 보세요.","answer_guide":{"answer":"예: 도장은 찍으면 왼쪽과 오른쪽이 통째로 바뀌므로 글자의 순서도 바뀌어 「이오」로 찍힌다. 「오이」로 찍히게 하려면 글자 하나하나뿐 아니라 「오이」 전체를 통째로 왼쪽이나 오른쪽으로 뒤집어 새겨야 한다. 그러면 도장에서는 「이」가 왼쪽, 「오」가 오른쪽에 거꾸로 새겨진다.","scoring_points":["「이오」로 찍힌다(순서가 바뀐다)고 썼는가","통째로 왼쪽·오른쪽으로 뒤집어 새긴다고 썼는가","글자 순서까지 바뀐다는 까닭을 썼는가"]},"explanation":["도장은 찍으면 좌우가 통째로 바뀌어요.","하나하나만 뒤집으면 순서가 거꾸로 찍혀요.","「오이」 전체를 통째로 뒤집어 새겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#1','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'mc','auto','평면도형을 돌리면 무엇이 변하나요?',ARRAY['M4-2-u6-X11']::text[],true,'{"seq":1,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"평면도형을 돌리면 무엇이 변하나요?","options":[{"t":"방향","correct":true},{"t":"모양","mis":"M4-2-u6-X11"},{"t":"크기","mis":"M4-2-u6-X11"},{"t":"개수","mis":"M4-2-u6-X11"}],"explanation":["도형을 돌려도 모양과 크기는 그대로예요.","돌리면 도형이 놓인 방향이 변해요.","돌리기를 말할 때는 시계 방향인지 시계 반대 방향인지와 몇 도인지를 함께 말해요."],"variant_rule":{"alt":[{"stem":"로니에게 도형을 돌리라고 할 때 함께 말해야 하는 것은 무엇인가요?","options":[{"t":"돌리는 방향(시계 방향·시계 반대 방향)과 각도","correct":true},{"t":"돌리는 방향만","mis":"M4-2-u6-X01"},{"t":"돌리는 각도만","mis":"M4-2-u6-X01"},{"t":"도형의 이름과 색","mis":"M4-2-u6-X01"}],"explanation":["도형을 돌려도 모양과 크기는 그대로예요.","돌리면 도형이 놓인 방향이 변해요.","돌리기를 말할 때는 시계 방향인지 시계 반대 방향인지와 몇 도인지를 함께 말해요."],"asset":null},{"stem":"집 모양을 시계 반대 방향으로 90°만큼 돌렸어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"모양은 그대로이고 방향이 바뀌었어요","correct":true},{"t":"모양이 달라졌어요","mis":"M4-2-u6-X11"},{"t":"크기가 커졌어요","mis":"M4-2-u6-X11"},{"t":"자리만 옮겨지고 방향은 그대로예요","mis":"M4-2-u6-X16"}],"explanation":["도형을 돌려도 모양과 크기는 그대로예요.","돌리면 도형이 놓인 방향이 변해요.","돌리기를 말할 때는 시계 방향인지 시계 반대 방향인지와 몇 도인지를 함께 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#2','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'sa','auto','도형을 시계 방향으로 90°만큼 돌리기를 4번 했어요. 모두 몇 도만큼 돌린 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u6-C7","difficulty":1,"kind":"sa","stem":"도형을 시계 방향으로 90°만큼 돌리기를 4번 했어요. 모두 몇 도만큼 돌린 것인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["한 번에 90°씩 돌렸어요.","4번이면 90°를 4번 더해요.","90 × 4 = 360 — 360°만큼 돌린 거예요 — 360°는 한 바퀴라 처음과 같아요."],"variant_rule":{"alt":[{"stem":"도형을 시계 방향으로 90°만큼 돌리기를 2번 했어요. 모두 몇 도만큼 돌린 것인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 번에 90°씩 돌렸어요.","2번이면 90°를 2번 더해요.","90 × 2 = 180 — 180°만큼 돌린 거예요."],"asset":null},{"stem":"도형을 시계 반대 방향으로 90°만큼 돌리기를 3번 했어요. 모두 몇 도만큼 돌린 것인가요? 숫자로 쓰세요.","answer":["270"],"explanation":["한 번에 90°씩 돌렸어요.","3번이면 90°를 3번 더해요.","90 × 3 = 270 — 270°만큼 돌린 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#3','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',1,'mc','auto','시계 반대 방향으로 90°만큼 돌린 것과 결과가 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X17','M4-2-u6-X16']::text[],true,'{"seq":3,"concept":"M4-2-u6-C8","difficulty":1,"kind":"mc","stem":"시계 반대 방향으로 90°만큼 돌린 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"시계 방향으로 270°만큼 돌리기","correct":true},{"t":"시계 방향으로 90°만큼 돌리기","mis":"M4-2-u6-X17"},{"t":"시계 방향으로 180°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌리기","mis":"M4-2-u6-X16"}],"explanation":["한 바퀴는 360°예요.","시계 반대 방향 90° = 시계 방향 270°처럼, 360°에서 뺀 만큼 반대쪽으로 돌리면 같아요.","180°는 어느 쪽으로 돌려도 같고, 360°는 처음과 같아요."],"variant_rule":{"alt":[{"stem":"시계 방향으로 90°만큼 돌린 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"시계 반대 방향으로 270°만큼 돌리기","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌리기","mis":"M4-2-u6-X17"},{"t":"시계 반대 방향으로 180°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X18"}],"explanation":["한 바퀴는 360°예요.","시계 반대 방향 90° = 시계 방향 270°처럼, 360°에서 뺀 만큼 반대쪽으로 돌리면 같아요.","180°는 어느 쪽으로 돌려도 같고, 360°는 처음과 같아요."],"asset":null},{"stem":"시계 방향으로 180°만큼 돌린 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"시계 반대 방향으로 180°만큼 돌리기","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X18"}],"explanation":["한 바퀴는 360°예요.","시계 반대 방향 90° = 시계 방향 270°처럼, 360°에서 뺀 만큼 반대쪽으로 돌리면 같아요.","180°는 어느 쪽으로 돌려도 같고, 360°는 처음과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#4','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'mc','auto','집 모양의 위쪽에 창문이 있어요. 집 모양을 시계 반대 방향으로 90°만큼 돌리면 창문은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":4,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"집 모양의 위쪽에 창문이 있어요. 집 모양을 시계 반대 방향으로 90°만큼 돌리면 창문은 어느 쪽으로 가나요?","options":[{"t":"왼쪽으로 가요","correct":true},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","위쪽에서 시곗바늘 반대쪽으로 90°만큼 따라가 봐요.","창문은 왼쪽으로 가요."],"variant_rule":{"alt":[{"stem":"집 모양의 위쪽에 굴뚝이 있어요. 집 모양을 시계 방향으로 90°만큼 돌리면 굴뚝은 어느 쪽으로 가나요?","options":[{"t":"오른쪽으로 가요","correct":true},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","위쪽에서 시곗바늘 쪽으로 90°만큼 따라가 봐요.","굴뚝은 오른쪽으로 가요."],"asset":null},{"stem":"집 모양의 위쪽에 문이 있어요. 집 모양을 시계 방향으로 180°만큼 돌리면 문은 어느 쪽으로 가나요?","options":[{"t":"아래쪽으로 가요","correct":true},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 180°만큼 돌리면 반 바퀴.","위쪽에서 시곗바늘 쪽으로 180°만큼 따라가 봐요.","문은 아래쪽으로 가요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#5','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',2,'mc','auto','처음 도형을 시계 방향으로 90°만큼 돌린 도형은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],true,'{"seq":5,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"처음 도형을 시계 방향으로 90°만큼 돌린 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X15"},{"t":"㉱","mis":"M4-2-u6-X16"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 가는지 따라가요.","시계 방향으로 90°만큼 돌리면 위쪽 부분이 오른쪽으로 가요.","뒤집은 모양이 아니라 돌린 모양 — ㉮예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[18.0,72.0],[54.0,72.0],[54.0,54.0],[36.0,54.0],[36.0,18.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[18.0,18.0],[18.0,54.0],[36.0,54.0],[36.0,36.0],[72.0,36.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[72.0,54.0],[72.0,18.0],[54.0,18.0],[54.0,36.0],[18.0,36.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,18.0],[54.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,18.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,72.0],[54.0,18.0],[18.0,18.0],[18.0,36.0],[36.0,36.0],[36.0,72.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"처음 도형을 시계 반대 방향으로 90°만큼 돌린 도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉯","mis":"M4-2-u6-X15"},{"t":"㉮","mis":"M4-2-u6-X16"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 가는지 따라가요.","시계 반대 방향으로 90°만큼 돌리면 위쪽 부분이 왼쪽으로 가요.","뒤집은 모양이 아니라 돌린 모양 — ㉱예요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[72.0,18.0],[54.0,18.0],[54.0,36.0],[36.0,36.0],[36.0,54.0],[54.0,54.0],[54.0,90.0],[72.0,90.0]]],"cap":"처음 도형"},{"w":108,"h":108,"grid":18,"poly":[[[36.0,90.0],[54.0,90.0],[54.0,72.0],[72.0,72.0],[72.0,54.0],[54.0,54.0],[54