INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#6','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',2,'mc','auto','점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":6,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 오른쪽에 있어요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":162,"h":90,"grid":18,"poly":[[[90.0,18.0],[90.0,36.0],[108.0,36.0],[108.0,54.0],[144.0,54.0],[144.0,18.0]]],"dash":[[[18.0,72.0],[36.0,72.0]],[[36.0,72.0],[36.0,54.0]],[[36.0,54.0],[54.0,54.0]],[[54.0,54.0],[54.0,18.0]],[[54.0,18.0],[18.0,18.0]],[[18.0,18.0],[18.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 반대 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 왼쪽에 있어요.","시계 반대 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"poly":[[[126.0,54.0],[126.0,72.0],[144.0,72.0],[144.0,54.0],[162.0,54.0],[162.0,36.0],[126.0,36.0],[126.0,18.0],[108.0,18.0],[108.0,54.0]]],"dash":[[[36.0,36.0],[18.0,36.0]],[[18.0,36.0],[18.0,54.0]],[[18.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,72.0]],[[36.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,36.0]],[[54.0,36.0],[72.0,36.0]],[[72.0,36.0],[72.0,18.0]],[[72.0,18.0],[36.0,18.0]],[[36.0,18.0],[36.0,36.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 아래쪽에 있어요.","시계 방향으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"poly":[[[162.0,90.0],[108.0,72.0],[144.0,54.0],[144.0,18.0],[162.0,18.0]]],"dash":[[[18.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[18.0,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#7','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',2,'sa','auto','시계 방향으로 270°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u6-C8","difficulty":2,"kind":"sa","stem":"시계 방향으로 270°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 270 = 90 — 90°예요."],"variant_rule":{"alt":[{"stem":"시계 방향으로 90°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["270"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 90 = 270 — 270°예요."],"asset":null},{"stem":"시계 반대 방향으로 270°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 270 = 90 — 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#8','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',2,'ox','auto','도형을 시계 방향으로 180°만큼 돌린 것과 시계 반대 방향으로 180°만큼 돌린 것은 결과가 같아요.',ARRAY['M4-2-u6-X15']::text[],true,'{"seq":8,"concept":"M4-2-u6-C8","difficulty":2,"kind":"ox","stem":"도형을 시계 방향으로 180°만큼 돌린 것과 시계 반대 방향으로 180°만큼 돌린 것은 결과가 같아요.","answer":"O","reason_options":[{"t":"180°는 반 바퀴라 어느 쪽으로 돌려도 같은 자리에 와서","correct":true},{"t":"돌리는 방향이 다르면 언제나 결과가 달라서","mis":"M4-2-u6-X15"}],"mis":"M4-2-u6-X15","explanation":["돌리면 모양은 그대로이고 방향이 변해요.","시계 반대 90° = 시계 270°, 180°는 어느 쪽이든 같고 360°는 처음과 같아요.","뒤집기와 돌리기는 다른 방법이에요."],"variant_rule":{"alt":[{"stem":"도형을 시계 방향으로 360°만큼 돌리면 처음 도형과 같아요.","answer":"O","reason_options":[{"t":"한 바퀴를 돌아 제자리로 와서","correct":true},{"t":"360°는 가장 많이 돌린 것이라 가장 많이 바뀌어서","mis":"M4-2-u6-X16"}],"explanation":["돌리면 모양은 그대로이고 방향이 변해요.","시계 반대 90° = 시계 270°, 180°는 어느 쪽이든 같고 360°는 처음과 같아요.","뒤집기와 돌리기는 다른 방법이에요."],"asset":null},{"stem":"시계 반대 방향으로 90°만큼 돌린 것은 시계 방향으로 90°만큼 돌린 것과 같아요.","answer":"X","reason_options":[{"t":"시계 반대 90°는 시계 방향 270°와 같아서","correct":true},{"t":"90°는 어느 쪽으로 돌려도 같아서","mis":"M4-2-u6-X17"}],"explanation":["돌리면 모양은 그대로이고 방향이 변해요.","시계 반대 90° = 시계 270°, 180°는 어느 쪽이든 같고 360°는 처음과 같아요.","뒤집기와 돌리기는 다른 방법이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_basic#9','math',4,2,'u6','L05','g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',2,'sa','auto','시계 방향으로 180°만큼 돌리는 것은 시계 방향으로 90°만큼 몇 번 돌리는 것과 같은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u6-C8","difficulty":2,"kind":"sa","stem":"시계 방향으로 180°만큼 돌리는 것은 시계 방향으로 90°만큼 몇 번 돌리는 것과 같은가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 번 돌릴 때마다 90°예요.","180°에는 90°가 2번 들어 있어요.","2번이에요."],"variant_rule":{"alt":[{"stem":"시계 반대 방향으로 270°만큼 돌리는 것은 시계 반대 방향으로 90°만큼 몇 번 돌리는 것과 같은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 번 돌릴 때마다 90°예요.","270°에는 90°가 3번 들어 있어요.","3번이에요."],"asset":null},{"stem":"시계 방향으로 360°만큼 돌리는 것은 시계 방향으로 90°만큼 몇 번 돌리는 것과 같은가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 번 돌릴 때마다 90°예요.","360°에는 90°가 4번 들어 있어요.","4번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
