INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_challenge#5','math',4,2,'u6','L05','g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',3,'sa','auto','퍼즐 조각(색칠한 도형)을 빈 곳(점선)에 꼭 맞게 넣으려고 해요. 조각을 시계 방향으로 몇 도만큼 돌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u6-C7","difficulty":3,"kind":"sa","stem":"퍼즐 조각(색칠한 도형)을 빈 곳(점선)에 꼭 맞게 넣으려고 해요. 조각을 시계 방향으로 몇 도만큼 돌려야 하나요? 숫자로 쓰세요.","answer":["90"],"explanation":["조각의 위쪽 부분이 빈 곳에서는 어디에 있는지 찾아요.","위쪽 부분이 오른쪽으로 갔어요.","시계 방향으로 90°만큼 돌려야 해요 — 시계 반대 방향으로 270°와 같아요."],"asset":{"type":"geo","items":[{"w":198,"h":108,"grid":18,"poly":[[[18.0,18.0],[18.0,72.0],[36.0,72.0],[36.0,90.0],[54.0,90.0],[54.0,54.0],[36.0,54.0],[36.0,18.0]]],"dash":[[[180.0,18.0],[126.0,18.0]],[[126.0,18.0],[126.0,36.0]],[[126.0,36.0],[108.0,36.0]],[[108.0,36.0],[108.0,54.0]],[[108.0,54.0],[144.0,54.0]],[[144.0,54.0],[144.0,36.0]],[[144.0,36.0],[180.0,36.0]],[[180.0,36.0],[180.0,18.0]]],"lab":[[[36.0,99.9],"조각"],[[144.0,99.9],"빈 곳"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 퍼즐 조각(색칠한 도형)을 빈 곳(점선)에 꼭 맞게 넣으려고 해요. 조각을 시계 방향으로 몇 도만큼 돌려야 하나요? 숫자로 쓰세요.","answer":["180"],"explanation":["조각의 위쪽 부분이 빈 곳에서는 어디에 있는지 찾아요.","위쪽 부분이 아래쪽으로 갔어요.","시계 방향으로 180°만큼 돌려야 해요."],"asset":{"type":"geo","items":[{"w":198,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"dash":[[[180.0,90.0],[126.0,72.0]],[[126.0,72.0],[162.0,54.0]],[[162.0,54.0],[162.0,18.0]],[[162.0,18.0],[180.0,18.0]],[[180.0,18.0],[180.0,90.0]]],"lab":[[[45.0,99.9],"조각"],[[153.0,99.9],"빈 곳"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 퍼즐 조각(색칠한 도형)을 빈 곳(점선)에 꼭 맞게 넣으려고 해요. 조각을 시계 방향으로 몇 도만큼 돌려야 하나요? 숫자로 쓰세요.","answer":["270"],"explanation":["조각의 위쪽 부분이 빈 곳에서는 어디에 있는지 찾아요.","위쪽 부분이 왼쪽으로 갔어요.","시계 방향으로 270°만큼 돌려야 해요 — 시계 반대 방향으로 90°와 같아요."],"asset":{"type":"geo","items":[{"w":198,"h"