INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L05_challenge#10','math',4,2,'u6','L05','g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',4,'essay','teacher','친구가 사각형을 「아래쪽으로 뒤집었어.」라며 그림을 그렸는데, 사실 그 그림은 시계 방향으로 180°만큼 돌린 그림이었어요. 뒤집기와 돌리기가 어떻게 다른지 쓰고, 두 결과가 같아 보이는 도형은 어떤 도형인지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"친구가 사각형을 「아래쪽으로 뒤집었어.」라며 그림을 그렸는데, 사실 그 그림은 시계 방향으로 180°만큼 돌린 그림이었어요. 뒤집기와 돌리기가 어떻게 다른지 쓰고, 두 결과가 같아 보이는 도형은 어떤 도형인지 써 보세요.","answer_guide":{"answer":"예: 아래쪽으로 뒤집으면 위쪽과 아래쪽만 서로 바뀌고 왼쪽과 오른쪽은 그대로이다. 시계 방향으로 180°만큼 돌리면 위쪽과 아래쪽, 왼쪽과 오른쪽이 모두 바뀐다. 그래서 두 결과는 보통 다르고, 왼쪽과 오른쪽 모양이 똑같은 도형일 때만 같아 보인다.","scoring_points":["아래쪽 뒤집기는 위아래만 바뀐다고 썼는가","180° 돌리기는 위아래·좌우가 모두 바뀐다고 썼는가","좌우 모양이 같은 도형만 결과가 같다고 썼는가"]},"explanation":["뒤집기: 위아래만 바뀌어요.","180° 돌리기: 위아래와 좌우가 모두 바뀌어요.","좌우가 똑같은 도형만 두 결과가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#1','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',1,'mc','auto','이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?',ARRAY['M4-2-u6-X19']::text[],true,'{"seq":1,"concept":"M4-2-u6-C9","difficulty":1,"kind":"mc","stem":"이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"오른쪽으로 뒤집기를 되풀이했어요","correct":true},{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","뒤집을 때마다 좌우가 바뀌어 두 모양이 번갈아 나와요.","오른쪽으로 뒤집기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,4.5],[34.5,4.5],[55.5,16.5]],[[64.5,4.5],[85.5,4.5],[64.5,16.5]],[[115.5,4.5],[94.5,4.5],[115.5,16.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","correct":true},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","시곗바늘 쪽으로 90°씩 돌아가 네 가지 모양이 차례로 나와요.","시계 방향으로 90°씩 돌리기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[7.5,3.6],[25.5,9.6],[12.0,15.0],[12.0,26.4],[7.5,26.4]],[[56.4,7.5],[50.4,25.5],[45.0,12.0],[33.6,12.0],[33.6,7.5]],[[82.5,26.4],[64.5,20.4],[78.0,15.0],[78.0,3.6],[82.5,3.6]],[[93.6,22.5],[99.6,4.5],[105.0,18.0],[116.4,18.0],[116.4,22.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"오른쪽으로 밀기를 되풀이했어요","correct":true},{"t":"시계 반대 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","모양이 그대로 되풀이돼요.","오른쪽으로 밀기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[34.5,4.5],[42.6,4.5],[42.6,18.6],[55.5,18.6],[55.5,25.5],[34.5,25.5]],[[64.5,4.5],[72.6,4.5],[72.6,18.6],[85.5,18.6],[85.5,25.5],[64.5,25.5]],[[94.5,4.5],[102.6,4.5],[102.6,18.6],[115.5,18.6],[115.5,25.5],[94.5,25.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
