INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#3','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',1,'sa','auto','한 줄에 모양이 4개씩 있고, 줄이 4개인 무늬를 만들었어요. 무늬의 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u6-C10","difficulty":1,"kind":"sa","stem":"한 줄에 모양이 4개씩 있고, 줄이 4개인 무늬를 만들었어요. 무늬의 모양은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 줄에 4개씩이에요.","그런 줄이 4개예요.","4 × 4 = 16개예요."],"variant_rule":{"alt":[{"stem":"첫째 줄에 모양 5개를 만든 다음, 그 줄을 아래쪽으로 뒤집어 줄을 늘려 모두 3줄인 무늬를 만들었어요. 무늬의 모양은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["줄을 늘려도 한 줄의 모양 수는 5개 그대로예요.","모두 3줄이에요.","5 × 3 = 15개예요."],"asset":null},{"stem":"한 줄에 모양이 6개씩 있고, 줄이 4개인 무늬를 만들었어요. 무늬의 모양은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["한 줄에 6개씩이에요.","그런 줄이 4개예요.","6 × 4 = 24개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
