4],[94.5,50.4],[108.0,45.0],[108.0,33.6],[112.5,33.6]],[[7.5,63.6],[25.5,69.6],[12.0,75.0],[12.0,86.4],[7.5,86.4]],[[52.5,86.4],[34.5,80.4],[48.0,75.0],[48.0,63.6],[52.5,63.6]],[[67.5,63.6],[85.5,69.6],[72.0,75.0],[72.0,86.4],[67.5,86.4]],[[112.5,86.4],[94.5,80.4],[108.0,75.0],[108.0,63.6],[112.5,63.6]]],"lab":[[[75.0,45.0],"?"]],"cap":"무늬"},{"w":30,"h":30,"grid":30,"poly":[[[22.5,3.6],[4.5,9.6],[18.0,15.0],[18.0,26.4],[22.5,26.4]]],"cap":"㉮"},{"w":30,"h":30,"grid":30,"poly":[[[7.5,3.6],[25.5,9.6],[12.0,15.0],[12.0,26.4],[7.5,26.4]]],"cap":"㉯"},{"w":30,"h":30,"grid":30,"poly":[[[22.5,26.4],[4.5,20.4],[18.0,15.0],[18.0,3.6],[22.5,3.6]]],"cap":"㉰"},{"w":30,"h":30,"grid":30,"poly":[[[7.5,26.4],[25.5,20.4],[12.0,15.0],[12.0,3.6],[7.5,3.6]]],"cap":"㉱"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#6','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',2,'sa','auto','모양 하나를 시계 방향으로 90°씩 돌리기를 되풀이하면 몇 번 만에 처음 모양으로 돌아오나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u6-C9","difficulty":2,"kind":"sa","stem":"모양 하나를 시계 방향으로 90°씩 돌리기를 되풀이하면 몇 번 만에 처음 모양으로 돌아오나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 번씩 움직일 때마다 모양을 그려 보며 세요.","90° × 4 = 360° — 한 바퀴예요.","4번 만에 처음 모양으로 돌아와요 — 그래서 무늬에 4가지 모양이 되풀이돼요."],"variant_rule":{"alt":[{"stem":"모양 하나를 오른쪽으로 뒤집기를 되풀이하면 몇 번 만에 처음 모양으로 돌아오나요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 번씩 움직일 때마다 모양을 그려 보며 세요.","두 번 뒤집으면 좌우가 다시 제자리예요.","2번 만에 처음 모양으로 돌아와요 — 그래서 무늬에 2가지 모양이 되풀이돼요."],"asset":null},{"stem":"모양 하나를 시계 방향으로 180°씩 돌리기를 되풀이하면 몇 번 만에 처음 모양으로 돌아오나요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 번씩 움직일 때마다 모양을 그려 보며 세요.","180° × 2 = 360° — 한 바퀴예요.","2번 만에 처음 모양으로 돌아와요 — 그래서 무늬에 2가지 모양이 되풀이돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#7','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',2,'sa','auto','모양 하나에서 시작해 오른쪽으로 뒤집기를 되풀이해 4칸짜리 한 줄을 만들었어요. 오른쪽으로 뒤집기를 몇 번 했나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u6-C9","difficulty":2,"kind":"sa","stem":"모양 하나에서 시작해 오른쪽으로 뒤집기를 되풀이해 4칸짜리 한 줄을 만들었어요. 오른쪽으로 뒤집기를 몇 번 했나요? 숫자로 쓰세요.","answer":["3"],"explanation":["첫 칸은 처음 모양 그대로예요.","둘째 칸부터 한 칸에 한 번씩 움직였어요.","4 − 1 = 3번이에요."],"variant_rule":{"alt":[{"stem":"모양 하나에서 시작해 시계 방향으로 90°만큼 돌리기를 되풀이해 5칸짜리 한 줄을 만들었어요. 시계 방향으로 90°만큼 돌리기를 몇 번 했나요? 숫자로 쓰세요.","answer":["4"],"explanation":["첫 칸은 처음 모양 그대로예요.","둘째 칸부터 한 칸에 한 번씩 움직였어요.","5 − 1 = 4번이에요."],"asset":null},{"stem":"모양 하나에서 시작해 오른쪽으로 밀기를 되풀이해 6칸짜리 한 줄을 만들었어요. 오른쪽으로 밀기를 몇 번 했나요? 숫자로 쓰세요.","answer":["5"],"explanation":["첫 칸은 처음 모양 그대로예요.","둘째 칸부터 한 칸에 한 번씩 움직였어요.","6 − 1 = 5번이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#8','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',2,'ox','auto','같은 무늬라도 여러 가지 방법으로 설명할 수 있어요.',ARRAY['M4-2-u6-X20']::text[],true,'{"seq":8,"concept":"M4-2-u6-C10","difficulty":2,"kind":"ox","stem":"같은 무늬라도 여러 가지 방법으로 설명할 수 있어요.","answer":"O","reason_options":[{"t":"오른쪽 뒤집기 = 왼쪽 뒤집기처럼 같은 결과를 내는 방법이 여러 가지라서","correct":true},{"t":"무늬를 설명하는 방법은 한 가지뿐이라서","mis":"M4-2-u6-X20"}],"mis":"M4-2-u6-X20","explanation":["무늬는 한 모양을 밀거나 뒤집거나 돌려 되풀이해 만들어요.","첫 줄을 만든 방법과 줄을 늘려 간 방법을 함께 말해요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"variant_rule":{"alt":[{"stem":"무늬를 만든 방법을 말할 때는 첫 줄을 만든 방법만 말하면 돼요.","answer":"X","reason_options":[{"t":"줄을 늘려 간 방법도 함께 말해야 해서","correct":true},{"t":"첫 줄만 보면 무늬 전체를 알 수 있어서","mis":"M4-2-u6-X19"}],"explanation":["무늬는 한 모양을 밀거나 뒤집거나 돌려 되풀이해 만들어요.","첫 줄을 만든 방법과 줄을 늘려 간 방법을 함께 말해요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":null},{"stem":"돌리기로는 무늬를 만들 수 없어요.","answer":"X","reason_options":[{"t":"모양을 90°씩 돌리기를 되풀이해도 무늬를 만들 수 있어서","correct":true},{"t":"무늬는 밀기와 뒤집기로만 만들어서","mis":"M4-2-u6-X19"}],"explanation":["무늬는 한 모양을 밀거나 뒤집거나 돌려 되풀이해 만들어요.","첫 줄을 만든 방법과 줄을 늘려 간 방법을 함께 말해요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_basic#9','math',4,2,'u6','L06','g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',2,'mc','auto','이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?',ARRAY['M4-2-u6-X19']::text[],true,'{"seq":9,"concept":"M4-2-u6-C9","difficulty":2,"kind":"mc","stem":"이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","correct":true},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 반대 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","반 바퀴씩 돌아 두 모양이 번갈아 나와요.","시계 방향으로 180°씩 돌리기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,25.5],[34.5,25.5],[55.5,13.5]],[[64.5,4.5],[85.5,4.5],[64.5,16.5]],[[115.5,25.5],[94.5,25.5],[115.5,13.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 반대 방향으로 90°씩 돌리기를 되풀이했어요","correct":true},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","시곗바늘 반대쪽으로 90°씩 돌아가 네 가지 모양이 차례로 나와요.","시계 반대 방향으로 90°씩 돌리기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[7.5,3.6],[25.5,9.6],[12.0,15.0],[12.0,26.4],[7.5,26.4]],[[33.6,22.5],[39.6,4.5],[45.0,18.0],[56.4,18.0],[56.4,22.5]],[[82.5,26.4],[64.5,20.4],[78.0,15.0],[78.0,3.6],[82.5,3.6]],[[116.4,7.5],[110.4,25.5],[105.0,12.0],[93.6,12.0],[93.6,7.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"아래쪽으로 뒤집기를 되풀이했어요","correct":true},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","위아래가 바뀐 두 모양이 번갈아 나와요.","아래쪽으로 뒤집기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[34.5,25.5],[42.6,25.5],[42.6,11.4],[55.5,11.4],[55.5,4.5],[34.5,4.5]],[[64.5,4.5],[72.6,4.5],[72.6,18.6],[85.5,18.6],[85.5,25.5],[64.5,25.5]],[[94.5,25.5],[102.6,25.5],[102.6,11.4],[115.5,11.4],[115.5,4.5],[94.5,4.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
