INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_challenge#5','math',4,2,'u6','L06','g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',3,'error','auto','무늬 만들기에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u6-X20','M4-2-u6-X21']::text[],true,'{"seq":5,"concept":"M4-2-u6-C10","difficulty":3,"kind":"error","stem":"무늬 만들기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「무늬를 만드는 방법은 한 가지로만 설명할 수 있어.」","correct":true,"mis_target":"M4-2-u6-X20"},{"t":"지아 — 「오른쪽으로 뒤집기와 왼쪽으로 뒤집기는 같은 무늬를 만들어.」","mis":"M4-2-u6-X21"},{"t":"준서 — 「90°씩 돌리기를 네 번 하면 처음 모양이 다시 나와.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「줄을 아래쪽으로 밀어서 늘릴 수도 있어.」","mis":"M4-2-u6-X21"}],"explanation":["무늬는 밀기·뒤집기·돌리기 모두로 만들 수 있어요.","첫 줄과 줄을 늘린 방법을 함께 말하고, 같은 무늬도 여러 방법으로 설명해요.","하랑의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"무늬 만들기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「첫 줄을 만든 방법만 말하면 무늬를 다 설명한 거야.」","correct":true,"mis_target":"M4-2-u6-X19"},{"t":"준서 — 「90°씩 돌리기를 네 번 하면 처음 모양이 다시 나와.」","mis":"M4-2-u6-X21"},{"t":"민서 — 「줄을 아래쪽으로 밀어서 늘릴 수도 있어.」","mis":"M4-2-u6-X21"},{"t":"도윤 — 「같은 무늬도 여러 방법으로 설명할 수 있어.」","mis":"M4-2-u6-X21"}],"explanation":["무늬는 밀기·뒤집기·돌리기 모두로 만들 수 있어요.","첫 줄과 줄을 늘린 방법을 함께 말하고, 같은 무늬도 여러 방법으로 설명해요.","지아의 말이 틀렸어요."],"asset":null},{"stem":"무늬 만들기에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「돌리기를 되풀이하면 끝없이 새 모양이 나와.」","correct":true,"mis_target":"M4-2-u6-X19"},{"t":"민서 — 「줄을 아래쪽으로 밀어서 늘릴 수도 있어.」","mis":"M4-2-u6-X21"},{"t":"도윤 — 「같은 무늬도 여러 방법으로 설명할 수 있어.」","mis":"M4-2-u6-X21"},{"t":"하윤 — 「무늬는 첫 줄과 줄을 늘린 방법으로 설명해.」","mis":"M4-2-u6-X21"}],"explanation":["무늬는 밀기·뒤집기·돌리기 모두로 만들 수 있어요.","첫 줄과 줄을 늘린 방법을 함께 말하고, 같은 무늬도 여러 방법으로 설명해요.","준서의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_code