INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_challenge#7','math',4,2,'u6','L06','g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',3,'mc','auto','이 한 줄을 보고 준서는 「오른쪽으로 뒤집기를 되풀이했어.」, 민서는 「왼쪽으로 뒤집기를 되풀이했어.」 했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-2-u6-X20','M4-2-u6-X19']::text[],true,'{"seq":7,"concept":"M4-2-u6-C10","difficulty":3,"kind":"mc","stem":"이 한 줄을 보고 준서는 「오른쪽으로 뒤집기를 되풀이했어.」, 민서는 「왼쪽으로 뒤집기를 되풀이했어.」 했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 사람 모두 바르게 말했어요","correct":true},{"t":"준서만 바르게 말했어요","mis":"M4-2-u6-X20"},{"t":"민서만 바르게 말했어요","mis":"M4-2-u6-X20"},{"t":"두 사람 모두 잘못 말했어요","mis":"M4-2-u6-X19"}],"explanation":["준서의 설명대로 해 보면 이 줄이 나와요.","민서의 설명대로 해도 결과가 같아요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[55.5,4.5],[47.4,4.5],[47.4,18.6],[34.5,18.6],[34.5,25.5],[55.5,25.5]],[[64.5,4.5],[72.6,4.5],[72.6,18.6],[85.5,18.6],[85.5,25.5],[64.5,25.5]],[[115.5,4.5],[107.4,4.5],[107.4,18.6],[94.5,18.6],[94.5,25.5],[115.5,25.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 한 줄을 보고 민서는 「시계 방향으로 90°씩 돌리기를 되풀이했어.」, 도윤은 「시계 반대 방향으로 270°씩 돌리기를 되풀이했어.」 했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 사람 모두 바르게 말했어요","correct":true},{"t":"민서만 바르게 말했어요","mis":"M4-2-u6-X20"},{"t":"도윤만 바르게 말했어요","mis":"M4-2-u6-X20"},{"t":"두 사람 모두 잘못 말했어요","mis":"M4-2-u6-X19"}],"explanation":["민서의 설명대로 해 보면 이 줄이 나와요.","도윤의 설명대로 해도 결과가 같아요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,4.5],[55.5,25.5],[43.5,4.5]],[[85.5,25.5],[64.5,25.5],[85.5,13.5]],[[94.5,25.5],[94.5,4.5],[106.5,25.5]]]}],"tag":false}},{"stem":"이 한 줄을 보고 도윤은 「시계 방향으로 180°씩 돌리기를 되풀이했어.」, 하윤은 「시계 반대 방향으로 180°씩 돌리기를 되풀이했어.」 했어요. 바르게 말한 것은 어느 것인가요?","option