INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_challenge#9','math',4,2,'u6','L06','g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C9',4,'sa','auto','이 줄의 규칙대로 모양을 계속 오른쪽으로 이어 가려고 해요. 10째 칸의 모양은 첫째 칸부터 4째 칸 가운데 몇째 칸의 모양과 같나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u6-C9","difficulty":4,"kind":"sa","stem":"이 줄의 규칙대로 모양을 계속 오른쪽으로 이어 가려고 해요. 10째 칸의 모양은 첫째 칸부터 4째 칸 가운데 몇째 칸의 모양과 같나요? 숫자로 쓰세요.","answer":["2"],"explanation":["시계 방향으로 90°씩 돌리기를 되풀이하면 모양 4가지가 차례로 되풀이돼요.","10 ÷ 4 = 2 …… 2 처럼 4칸씩 묶어 남는 수를 봐요.","10째 칸은 2째 칸과 같아요."],"asset":{"type":"geo","items":[{"w":150,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,4.5],[55.5,25.5],[43.5,4.5]],[[85.5,25.5],[64.5,25.5],[85.5,13.5]],[[94.5,25.5],[94.5,4.5],[106.5,25.5]],[[124.5,4.5],[145.5,4.5],[124.5,16.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 줄의 규칙대로 모양을 계속 오른쪽으로 이어 가려고 해요. 15째 칸의 모양은 첫째 칸부터 2째 칸 가운데 몇째 칸의 모양과 같나요? 숫자로 쓰세요.","answer":["1"],"explanation":["오른쪽으로 뒤집기를 되풀이하면 모양 2가지가 차례로 되풀이돼요.","15 ÷ 2 = 7 …… 1 처럼 2칸씩 묶어 남는 수를 봐요.","15째 칸은 1째 칸과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":30,"grid":30,"poly":[[[7.5,3.6],[25.5,9.6],[12.0,15.0],[12.0,26.4],[7.5,26.4]],[[52.5,3.6],[34.5,9.6],[48.0,15.0],[48.0,26.4],[52.5,26.4]],[[67.5,3.6],[85.5,9.6],[72.0,15.0],[72.0,26.4],[67.5,26.4]]]}],"tag":false}},{"stem":"이 줄의 규칙대로 모양을 계속 오른쪽으로 이어 가려고 해요. 13째 칸의 모양은 첫째 칸부터 4째 칸 가운데 몇째 칸의 모양과 같나요? 숫자로 쓰세요.","answer":["1"],"explanation":["시계 반대 방향으로 90°씩 돌리기를 되풀이하면 모양 4가지가 차례로 되풀이돼요.","13 ÷ 4 = 3 …… 1 처럼 4칸씩 묶어 남는 수를 봐요.","13째 칸은 1째 칸과 같아요."],"asset":{"type":"geo","items":[{"w":150,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[34.5,25.5],[34.5,17.4],[48.6,17.4],[48.6,4.5],[55.5,4.5],[55.5,25.5]],[[85.5,25.5],[77.4,25.5],[77.4,11.4],[64.5,11.4],[64.5,4.5],[85.5,4.5]],[[115.5,4.5],[115.5,12.6],[101.4,12.6],[101.4,25.5],[94.5,25.5],[94.5,4.5]],[[124.5,4.5],[132.6,4.5],[132.6,18.6],[145.5,18.6],[145.5,25.5],[124.5,25.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_L06_challenge#10','math',4,2,'u6','L06','g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',4,'essay','teacher','삼각형 모양 하나로 무늬를 만들었어요. 첫 줄은 시계 방향으로 90°씩 돌리기를 되풀이했고, 그 줄을 아래쪽으로 뒤집어 둘째 줄을 만들었어요. 이 무늬를 만든 방법을 다른 말로 한 가지 더 설명하고, 첫 줄에 모양이 몇 가지 되풀이되는지와 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C10","difficulty":4,"kind":"essay","stem":"삼각형 모양 하나로 무늬를 만들었어요. 첫 줄은 시계 방향으로 90°씩 돌리기를 되풀이했고, 그 줄을 아래쪽으로 뒤집어 둘째 줄을 만들었어요. 이 무늬를 만든 방법을 다른 말로 한 가지 더 설명하고, 첫 줄에 모양이 몇 가지 되풀이되는지와 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 첫 줄은 시계 반대 방향으로 270°씩 돌리기를 되풀이했다고 말할 수도 있다(시계 방향 90° = 시계 반대 방향 270°). 둘째 줄은 위쪽으로 뒤집었다고 말해도 된다. 90°씩 네 번 돌리면 360°로 처음 모양이 되므로 첫 줄에는 네 가지 모양이 되풀이된다.","scoring_points":["같은 결과의 다른 설명(시계 반대 270° 또는 위쪽 뒤집기)을 썼는가","첫 줄과 줄을 늘린 방법을 함께 썼는가","네 가지 모양이 되풀이되는 까닭(4번 = 360°)을 썼는가"]},"explanation":["시계 방향 90° = 시계 반대 방향 270°, 아래쪽 뒤집기 = 위쪽 뒤집기.","첫 줄을 만든 방법과 줄을 늘린 방법을 함께 말해요.","네 번 돌리면 360° — 네 가지 모양이 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#1','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C1',1,'mc','auto','점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03','M4-2-u6-X01']::text[],true,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"오른쪽으로 2 cm","correct":true},{"t":"왼쪽으로 2 cm","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 3 cm","mis":"M4-2-u6-X03"},{"t":"2 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 오른쪽에 있어요.","선을 넘을 때마다 하나씩 세면 2칸, 한 칸이 1 cm라서 2 cm예요.","점 ㄱ을 오른쪽으로 2 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[72,36,"w"],"ㄴ":[108,36,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"위쪽으로 4 cm","correct":true},{"t":"아래쪽으로 4 cm","mis":"M4-2-u6-X02"},{"t":"위쪽으로 5 cm","mis":"M4-2-u6-X03"},{"t":"4 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 위쪽에 있어요.","선을 넘을 때마다 하나씩 세면 4칸, 한 칸이 1 cm라서 4 cm예요.","점 ㄱ을 위쪽으로 4 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[108,90,"s"],"ㄴ":[108,18,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"왼쪽으로 2 cm","correct":true},{"t":"오른쪽으로 2 cm","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 3 cm","mis":"M4-2-u6-X03"},{"t":"2 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 왼쪽에 있어요.","선을 넘을 때마다 하나씩 세면 2칸, 한 칸이 1 cm라서 2 cm예요.","점 ㄱ을 왼쪽으로 2 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[54,36,"e"],"ㄴ":[18,36,"w"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#2','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C2',1,'sa','auto','한 칸이 1 cm인 모눈에서 점을 왼쪽으로 4 cm 옮겼어요. 몇 칸 옮긴 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u6-C2","difficulty":1,"kind":"sa","stem":"한 칸이 1 cm인 모눈에서 점을 왼쪽으로 4 cm 옮겼어요. 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["모눈 한 칸은 1 cm예요.","4 cm는 1 cm가 4개예요.","4칸 옮긴 거예요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm인 모눈에서 점을 오른쪽으로 6칸 옮겼어요. 점을 처음 자리로 되돌리려면 왼쪽으로 몇 cm 옮겨야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["오른쪽과 왼쪽은 서로 되돌리는 방향이에요.","같은 칸 수만큼 반대로 옮기면 처음 자리예요.","6칸 = 6 cm예요."],"asset":null},{"stem":"한 칸이 1 cm인 모눈에서 점을 위쪽으로 7 cm 옮겼어요. 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["모눈 한 칸은 1 cm예요.","7 cm는 1 cm가 7개예요.","7칸 옮긴 거예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#3','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C3',1,'mc','auto','밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X02']::text[],true,'{"seq":3,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"오른쪽으로 밀었어요","correct":true},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 오른쪽에 있어요.","오른쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[72.0,18.0],[72.0,72.0],[90.0,72.0],[90.0,90.0],[108.0,90.0],[108.0,54.0],[90.0,54.0],[90.0,18.0]]],"dash":[[[18.0,18.0],[18.0,72.0]],[[18.0,72.0],[36.0,72.0]],[[36.0,72.0],[36.0,90.0]],[[36.0,90.0],[54.0,90.0]],[[54.0,90.0],[54.0,54.0]],[[54.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,18.0]],[[36.0,18.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 밀었어요","correct":true},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 아래쪽에 있어요.","아래쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":90,"h":162,"grid":18,"poly":[[[18.0,108.0],[72.0,108.0],[18.0,144.0]]],"dash":[[[18.0,18.0],[72.0,18.0]],[[72.0,18.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"위쪽으로 밀었어요","correct":true},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 위쪽에 있어요.","위쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":72,"h":198,"grid":18,"poly":[[[18.0,18.0],[18.0,72.0],[36.0,72.0],[36.0,90.0],[54.0,90.0],[54.0,54.0],[36.0,54.0],[36.0,18.0]]],"dash":[[[18.0,108.0],[18.0,162.0]],[[18.0,162.0],[36.0,162.0]],[[36.0,162.0],[36.0,180.0]],[[36.0,180.0],[54.0,180.0]],[[54.0,180.0],[54.0,144.0]],[[54.0,144.0],[36.0,144.0]],[[36.0,144.0],[36.0,108.0]],[[36.0,108.0],[18.0,108.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#4','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C4',1,'sa','auto','삼각형을 오른쪽으로 6칸 밀었어요. 왼쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u6-C4","difficulty":1,"kind":"sa","stem":"삼각형을 오른쪽으로 6칸 밀었어요. 왼쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["6"],"explanation":["오른쪽과 왼쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","왼쪽으로 6칸 밀면 처음 자리예요."],"variant_rule":{"alt":[{"stem":"삼각형을 아래쪽으로 8칸 밀었어요. 위쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["8"],"explanation":["아래쪽과 위쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","위쪽으로 8칸 밀면 처음 자리예요."],"asset":null},{"stem":"삼각형을 왼쪽으로 4칸 밀었어요. 오른쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["4"],"explanation":["왼쪽과 오른쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","오른쪽으로 4칸 밀면 처음 자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#5','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C5',1,'mc','auto','도형을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],true,'{"seq":5,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"도형을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"왼쪽과 오른쪽","correct":true},{"t":"위쪽과 아래쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"variant_rule":{"alt":[{"stem":"도형을 위쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"위쪽과 아래쪽","correct":true},{"t":"왼쪽과 오른쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null},{"stem":"도형의 왼쪽에 있던 부분이 오른쪽으로 갔어요. 어떻게 뒤집은 것인가요?","options":[{"t":"왼쪽이나 오른쪽으로 뒤집었어요","correct":true},{"t":"위쪽이나 아래쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X11"},{"t":"크기를 바꾸었어요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#6','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C6',1,'mc','auto','사각형을 위쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X11']::text[],true,'{"seq":6,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"사각형을 위쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"아래쪽으로 뒤집기","correct":true},{"t":"왼쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"오른쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"위쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"오른쪽으로 뒤집기","correct":true},{"t":"위쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"왼쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null},{"stem":"삼각형을 아래쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"위쪽으로 뒤집기","correct":true},{"t":"오른쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"왼쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"아래쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#7','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C7',1,'mc','auto','집 모양의 오른쪽에 창문이 있어요. 집 모양을 시계 반대 방향으로 90°만큼 돌리면 창문은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":7,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"집 모양의 오른쪽에 창문이 있어요. 집 모양을 시계 반대 방향으로 90°만큼 돌리면 창문은 어느 쪽으로 가나요?","options":[{"t":"위쪽으로 가요","correct":true},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","오른쪽에서 시곗바늘 반대쪽으로 90°만큼 따라가 봐요.","창문은 위쪽으로 가요."],"variant_rule":{"alt":[{"stem":"집 모양의 오른쪽에 굴뚝이 있어요. 집 모양을 시계 방향으로 90°만큼 돌리면 굴뚝은 어느 쪽으로 가나요?","options":[{"t":"아래쪽으로 가요","correct":true},{"t":"위쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","오른쪽에서 시곗바늘 쪽으로 90°만큼 따라가 봐요.","굴뚝은 아래쪽으로 가요."],"asset":null},{"stem":"집 모양의 오른쪽에 문이 있어요. 집 모양을 시계 방향으로 180°만큼 돌리면 문은 어느 쪽으로 가나요?","options":[{"t":"왼쪽으로 가요","correct":true},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 180°만큼 돌리면 반 바퀴.","오른쪽에서 시곗바늘 쪽으로 180°만큼 따라가 봐요.","문은 왼쪽으로 가요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#8','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C9',1,'mc','auto','이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?',ARRAY['M4-2-u6-X19']::text[],true,'{"seq":8,"concept":"M4-2-u6-C9","difficulty":1,"kind":"mc","stem":"이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"오른쪽으로 밀기를 되풀이했어요","correct":true},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","모양이 그대로 되풀이돼요.","오른쪽으로 밀기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[34.5,4.5],[42.6,4.5],[42.6,18.6],[55.5,18.6],[55.5,25.5],[34.5,25.5]],[[64.5,4.5],[72.6,4.5],[72.6,18.6],[85.5,18.6],[85.5,25.5],[64.5,25.5]],[[94.5,4.5],[102.6,4.5],[102.6,18.6],[115.5,18.6],[115.5,25.5],[94.5,25.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","correct":true},{"t":"시계 반대 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","반 바퀴씩 돌아 두 모양이 번갈아 나와요.","시계 방향으로 180°씩 돌리기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,25.5],[34.5,25.5],[55.5,13.5]],[[64.5,4.5],[85.5,4.5],[64.5,16.5]],[[115.5,25.5],[94.5,25.5],[115.5,13.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 반대 방향으로 90°씩 돌리기를 되풀이했어요","correct":true},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","시곗바늘 반대쪽으로 90°씩 돌아가 네 가지 모양이 차례로 나와요.","시계 반대 방향으로 90°씩 돌리기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[7.5,3.6],[25.5,9.6],[12.0,15.0],[12.0,26.4],[7.5,26.4]],[[33.6,22.5],[39.6,4.5],[45.0,18.0],[56.4,18.0],[56.4,22.5]],[[82.5,26.4],[64.5,20.4],[78.0,15.0],[78.0,3.6],[82.5,3.6]],[[116.4,7.5],[110.4,25.5],[105.0,12.0],[93.6,12.0],[93.6,7.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#9','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C1',2,'mc','auto','점 ㄱ을 오른쪽으로 2칸 옮기고 위쪽으로 1칸 옮겼을 때의 점은 어느 것인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":9,"concept":"M4-2-u6-C1","difficulty":2,"kind":"mc","stem":"점 ㄱ을 오른쪽으로 2칸 옮기고 위쪽으로 1칸 옮겼을 때의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X06"},{"t":"점 ㄹ","mis":"M4-2-u6-X02"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"}],"explanation":["점 ㄱ에서 먼저 오른쪽으로 2칸 옮겨요.","그 자리에서 위쪽으로 1칸 옮겨요.","도착한 점은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[108,72,"s"],"ㄴ":[144,54,"sw"],"ㄷ":[162,54,"e"],"ㄹ":[72,54,"w"],"ㅁ":[126,36,"nw"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㄱ을 아래쪽으로 1칸 옮기고 오른쪽으로 2칸 옮겼을 때의 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄴ","mis":"M4-2-u6-X02"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"}],"explanation":["점 ㄱ에서 먼저 아래쪽으로 1칸 옮겨요.","그 자리에서 오른쪽으로 2칸 옮겨요.","도착한 점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[54,36,"n"],"ㄴ":[18,54,"w"],"ㄷ":[108,54,"e"],"ㄹ":[72,72,"sw"],"ㅁ":[90,54,"nw"]}}],"tag":false}},{"stem":"점 ㄱ을 왼쪽으로 2칸 옮기고 위쪽으로 1칸 옮겼을 때의 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"}],"explanation":["점 ㄱ에서 먼저 왼쪽으로 2칸 옮겨요.","그 자리에서 위쪽으로 1칸 옮겨요.","도착한 점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":126,"grid":18,"pts":{"ㄱ":[126,72,"s"],"ㄴ":[72,54,"w"],"ㄷ":[162,54,"e"],"ㄹ":[108,36,"ne"],"ㅁ":[90,54,"se"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_c