INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#16','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',2,'sa','auto','시계 반대 방향으로 270°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u6-C8","difficulty":2,"kind":"sa","stem":"시계 반대 방향으로 270°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 270 = 90 — 90°예요."],"variant_rule":{"alt":[{"stem":"시계 반대 방향으로 90°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["270"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 90 = 270 — 270°예요."],"asset":null},{"stem":"시계 방향으로 180°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 180 = 180 — 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
