INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#19','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C7',3,'mc','auto','점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?',ARRAY['M4-2-u6-X16']::text[],true,'{"seq":19,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 아래쪽에 있어요.","시계 방향으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":144,"h":90,"grid":18,"poly":[[[126.0,18.0],[108.0,18.0],[108.0,36.0],[90.0,36.0],[90.0,72.0],[126.0,72.0]]],"dash":[[[18.0,72.0],[36.0,72.0]],[[36.0,72.0],[36.0,54.0]],[[36.0,54.0],[54.0,54.0]],[[54.0,54.0],[54.0,18.0]],[[54.0,18.0],[18.0,18.0]],[[18.0,18.0],[18.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 오른쪽에 있어요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"poly":[[[144.0,36.0],[144.0,18.0],[126.0,18.0],[126.0,36.0],[108.0,36.0],[108.0,54.0],[144.0,54.0],[144.0,72.0],[162.0,72.0],[162.0,36.0]]],"dash":[[[36.0,36.0],[18.0,36.0]],[[18.0,36.0],[18.0,54.0]],[[18.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,72.0]],[[36.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,36.0]],[[54.0,36.0],[72.0,36.0]],[[72.0,36.0],[72.0,18.0]],[[72.0,18.0],[36.0,18.0]],[[36.0,18.0],[36.0,36.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니