INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_a#22','math',4,2,'u6','','g4_2_math_u6_review_a','unit_review','M4-2-u6-C2',3,'mc','auto','점 ㄴ은 점 ㄱ을 왼쪽으로 4칸 옮기고 아래쪽으로 3칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X02']::text[],true,'{"seq":22,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"점 ㄴ은 점 ㄱ을 왼쪽으로 4칸 옮기고 아래쪽으로 3칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"오른쪽으로 4칸 옮기고 위쪽으로 3칸 옮겨요","correct":true},{"t":"왼쪽으로 4칸 옮기고 아래쪽으로 3칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"오른쪽으로 3칸 옮기고 위쪽으로 4칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 4칸 옮기고 아래쪽으로 3칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","왼쪽의 반대는 오른쪽, 아래쪽의 반대는 위쪽이에요.","칸 수는 그대로 — 오른쪽으로 4칸 옮기고 위쪽으로 3칸 옮기면 돼요."],"variant_rule":{"alt":[{"stem":"점 ㄴ은 점 ㄱ을 오른쪽으로 4칸 옮기고 아래쪽으로 5칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"왼쪽으로 4칸 옮기고 위쪽으로 5칸 옮겨요","correct":true},{"t":"오른쪽으로 4칸 옮기고 아래쪽으로 5칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"왼쪽으로 5칸 옮기고 위쪽으로 4칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 4칸 옮기고 아래쪽으로 5칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","오른쪽의 반대는 왼쪽, 아래쪽의 반대는 위쪽이에요.","칸 수는 그대로 — 왼쪽으로 4칸 옮기고 위쪽으로 5칸 옮기면 돼요."],"asset":null},{"stem":"점 ㄴ은 점 ㄱ을 왼쪽으로 4칸 옮기고 아래쪽으로 2칸 옮긴 점이에요. 점 ㄴ을 처음 자리(점 ㄱ)로 되돌리려면 어떻게 옮겨야 하나요?","options":[{"t":"오른쪽으로 4칸 옮기고 위쪽으로 2칸 옮겨요","correct":true},{"t":"왼쪽으로 4칸 옮기고 아래쪽으로 2칸 옮겨요","mis":"M4-2-u6-X07"},{"t":"오른쪽으로 2칸 옮기고 위쪽으로 4칸 옮겨요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 4칸 옮기고 아래쪽으로 2칸 옮겨요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 옮긴 방향의 반대로 옮겨요.","왼쪽의 반대는 오른쪽, 아래쪽의 반대는 위쪽이에요.","칸 수는 그대로 — 오른쪽으로 4칸 옮기고 위쪽으로 2칸 옮기면 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misco