INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_b#16','math',4,2,'u6','','g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',2,'sa','auto','시계 반대 방향으로 90°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u6-C8","difficulty":2,"kind":"sa","stem":"시계 반대 방향으로 90°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["270"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 90 = 270 — 270°예요."],"variant_rule":{"alt":[{"stem":"시계 방향으로 180°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 180 = 180 — 180°예요."],"asset":null},{"stem":"시계 반대 방향으로 180°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 180 = 180 — 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_b#17','math',4,2,'u6','','g4_2_math_u6_review_b','unit_review','M4-2-u6-C4',3,'mc','auto','도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":17,"concept":"M4-2-u6-C4","difficulty":3,"kind":"mc","stem":"도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 4칸 밀고 왼쪽으로 1칸 밀었어요","correct":true},{"t":"왼쪽으로 4칸 밀고 아래쪽으로 1칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 1칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 2칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 왼쪽으로 1칸, 세로로 아래쪽으로 4칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":108,"h":144,"grid":18,"poly":[[[18.0,90.0],[54.0,90.0],[72.0,126.0],[18.0,126.0]]],"dash":[[[36.0,18.0],[72.0,18.0]],[[72.0,18.0],[90.0,54.0]],[[90.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"오른쪽으로 5칸 밀고 아래쪽으로 4칸 밀었어요","correct":true},{"t":"오른쪽으로 4칸 밀고 아래쪽으로 5칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 5칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 6칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 오른쪽으로 5칸, 세로로 아래쪽으로 4칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"grid":18,"poly":[[[108.0,90.0],[162.0,108.0],[126.0,126.0],[126.0,162.0],[108.0,162.0]]],"dash":[[[18.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[18.0,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 3칸 밀고 왼쪽으로 