INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_b#18','math',4,2,'u6','','g4_2_math_u6_review_b','unit_review','M4-2-u6-C6',3,'mc','auto','처음 도형을 오른쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?',ARRAY['M4-2-u6-X13','M4-2-u6-X10','M4-2-u6-X18']::text[],true,'{"seq":18,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"처음 도형을 오른쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X13"},{"t":"㉱","mis":"M4-2-u6-X10"},{"t":"㉯","mis":"M4-2-u6-X18"}],"explanation":["한 번 뒤집으면 좌우가 바뀌어요.","한 번 더 같은 쪽으로 뒤집으면 다시 바뀌어 제자리예요.","같은 쪽으로 두 번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"처음 도형"},{"w":90,"h":108,"grid":18,"poly":[[[72.0,18.0],[18.0,36.0],[54.0,54.0],[54.0,90.0],[72.0,90.0]]],"cap":"㉮"},{"w":90,"h":108,"grid":18,"poly":[[[72.0,90.0],[18.0,72.0],[54.0,54.0],[54.0,18.0],[72.0,18.0]]],"cap":"㉯"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"㉰"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,90.0],[72.0,72.0],[36.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"처음 도형을 위쪽으로 뒤집은 다음 왼쪽으로 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X13"},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉱","mis":"M4-2-u6-X10"}],"explanation":["먼저 위쪽으로 뒤집으면 위아래가 바뀌어요.","이어서 왼쪽으로 뒤집으면 좌우가 바뀌어요 — 좌우와 위아래가 모두 바뀌어요.","서로 다른 쪽으로 두 번 뒤집으면 처음으로 돌아오지 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,18.0],[36.0,18.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,