INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_b#19','math',4,2,'u6','','g4_2_math_u6_review_b','unit_review','M4-2-u6-C7',3,'mc','auto','점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":19,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 오른쪽에 있어요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"poly":[[[144.0,36.0],[144.0,18.0],[126.0,18.0],[126.0,36.0],[108.0,36.0],[108.0,54.0],[144.0,54.0],[144.0,72.0],[162.0,72.0],[162.0,36.0]]],"dash":[[[36.0,36.0],[18.0,36.0]],[[18.0,36.0],[18.0,54.0]],[[18.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,72.0]],[[36.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,36.0]],[[54.0,36.0],[72.0,36.0]],[[72.0,36.0],[72.0,18.0]],[[72.0,18.0],[36.0,18.0]],[[36.0,18.0],[36.0,36.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 반대 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 왼쪽에 있어요.","시계 반대 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":198,"h":108,"grid":18,"poly":[[[108.0,72.0],[126.0,18.0],[144.0,54.0],[180.0,54.0],[180.0,72.0]]],"dash":[[[18.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[18.0,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 아래쪽에 있어요.","시계 방향으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":144,"h":108,"grid":18,"poly":[[[90.0,90.0],[108.0,90.0],[108.0,72.0],[126.0,72.0],[126.0,54.0],[108.0,54.0],[108.0,18.0],[90.0,18.0]]],"dash":[[[54.0,18.0],[36.0,18.0]],[[36.0,18.0],[36.0,36.0]],[[36.0,36.0],[18.0,36.0]],[[18.0,36.0],[18.0,54.0]],[[18.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[54.0,90.0]],[[54.0,90.0],[54.0,18.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_b#20','math',4,2,'u6','','g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',3,'mc','auto','아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X18']::text[],true,'{"seq":20,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉰","mis":"M4-2-u6-X18"},{"t":"㉮","mis":"M4-2-u6-X18"},{"t":"㉯","mis":"M4-2-u6-X18"}],"explanation":["180°만큼 돌리면 위아래와 좌우가 모두 바뀌고, 아래쪽으로 뒤집으면 위아래만 바뀌어요.","그래서 왼쪽과 오른쪽이 똑같은 도형만 두 결과가 같아요.","㉱는 왼쪽과 오른쪽 모양이 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[36.0,18.0],[36.0,72.0],[72.0,72.0],[72.0,54.0],[54.0,54.0],[54.0,18.0]]],"cap":"㉮"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[90.0,72.0],[90.0,18.0],[36.0,18.0]]],"cap":"㉯"},{"w":126,"h":108,"grid":18,"poly":[[[54.0,36.0],[36.0,36.0],[36.0,54.0],[54.0,54.0],[54.0,72.0],[72.0,72.0],[72.0,36.0],[90.0,36.0],[90.0,18.0],[54.0,18.0]]],"cap":"㉰"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[54.0,18.0],[72.0,36.0],[72.0,72.0],[36.0,72.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X18"},{"t":"㉰","mis":"M4-2-u6-X18"},{"t":"㉱","mis":"M4-2-u6-X18"}],"explanation":["180°만큼 돌리면 위아래와 좌우가 모두 바뀌고, 아래쪽으로 뒤집으면 위아래만 바뀌어요.","그래서 왼쪽과 오른쪽이 똑같은 도형만 두 결과가 같아요.","㉮는 왼쪽과 오른쪽 모양이 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[36.0,54.0],[54.0,54.0],[54.0,72.0],[72.0,72.0],[72.0,54.0],[90.0,54.0],[90.0,36.0],[36.0,36.0]]],"cap":"㉮"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[90.0,72.0],[90.0