INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#14','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',2,'sa','auto','도형을 오른쪽으로 7번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M4-2-u6-C6","difficulty":2,"kind":"sa","stem":"도형을 오른쪽으로 7번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["1"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","7번은 두 번씩 3묶음과 한 번 더예요.","한 번 뒤집은 것과 같아요 — 1을 써요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 6번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["0"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","6번은 두 번씩 3묶음이에요.","처음 도형과 같아요 — 0을 써요."],"asset":null},{"stem":"도형을 아래쪽으로 3번 뒤집었어요. 한 번만 뒤집은 것과 결과가 같으면 1, 뒤집지 않은 처음 도형과 같으면 0을 쓰세요.","answer":["1"],"explanation":["같은 쪽으로 두 번 뒤집으면 처음 도형으로 돌아와요.","3번은 두 번씩 1묶음과 한 번 더예요.","한 번 뒤집은 것과 같아요 — 1을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
