INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#16','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C8',2,'sa','auto','시계 방향으로 180°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-2-u6-C8","difficulty":2,"kind":"sa","stem":"시계 방향으로 180°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 180 = 180 — 180°예요."],"variant_rule":{"alt":[{"stem":"시계 반대 방향으로 180°만큼 돌린 것은 시계 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 180 = 180 — 180°예요."],"asset":null},{"stem":"시계 방향으로 270°만큼 돌린 것은 시계 반대 방향으로 몇 도만큼 돌린 것과 같은가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴는 360°예요.","반대쪽으로 돌릴 때는 360°에서 빼요.","360 − 270 = 90 — 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#17','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C4',3,'mc','auto','도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":17,"concept":"M4-2-u6-C4","difficulty":3,"kind":"mc","stem":"도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"오른쪽으로 5칸 밀고 아래쪽으로 4칸 밀었어요","correct":true},{"t":"오른쪽으로 4칸 밀고 아래쪽으로 5칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 5칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 6칸 밀고 아래쪽으로 4칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 오른쪽으로 5칸, 세로로 아래쪽으로 4칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"grid":18,"poly":[[[108.0,90.0],[162.0,108.0],[126.0,126.0],[126.0,162.0],[108.0,162.0]]],"dash":[[[18.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[18.0,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 3칸 밀고 왼쪽으로 5칸 밀었어요","correct":true},{"t":"왼쪽으로 3칸 밀고 아래쪽으로 5칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 5칸 밀고 아래쪽으로 3칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 6칸 밀고 아래쪽으로 3칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 왼쪽으로 5칸, 세로로 아래쪽으로 3칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":180,"h":144,"grid":18,"poly":[[[36.0,90.0],[18.0,90.0],[18.0,108.0],[36.0,108.0],[36.0,126.0],[54.0,126.0],[54.0,90.0],[72.0,90.0],[72.0,72.0],[36.0,72.0]]],"dash":[[[126.0,36.0],[108.0,36.0]],[[108.0,36.0],[108.0,54.0]],[[108.0,54.0],[126.0,54.0]],[[126.0,54.0],[126.0,72.0]],[[126.0,72.0],[144.0,72.0]],[[144.0,72.0],[144.0,36.0]],[[144.0,36.0],[162.0,36.0]],[[162.0,36.0],[162.0,18.0]],[[162.0,18.0],[126.0,18.0]],[[126.0,18.0],[126.0,36.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 도형을 어떻게 밀었는지 바르게 설명한 것은 어느 것인가요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"왼쪽으로 5칸 밀고 위쪽으로 2칸 밀었어요","correct":true},{"t":"왼쪽으로 2칸 밀고 위쪽으로 5칸 밀었어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 5칸 밀고 위쪽으로 2칸 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 6칸 밀고 위쪽으로 2칸 밀었어요","mis":"M4-2-u6-X03"}],"explanation":["같은 꼭짓점 하나를 골라 가로로, 세로로 몇 칸 옮겨졌는지 세요.","가로로 왼쪽으로 5칸, 세로로 위쪽으로 2칸이에요.","말하는 순서를 바꾸어도 도착하는 자리는 같아요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[18.0,54.0]]],"dash":[[[108.0,54.0],[162.0,54.0]],[[162.0,54.0],[108.0,90.0]],[[108.0,90.0],[108.0,54.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#18','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',3,'mc','auto','처음 도형을 위쪽으로 뒤집은 다음 왼쪽으로 뒤집었어요. 그 결과는 어느 것인가요?',ARRAY['M4-2-u6-X13','M4-2-u6-X10']::text[],true,'{"seq":18,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"처음 도형을 위쪽으로 뒤집은 다음 왼쪽으로 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X13"},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉱","mis":"M4-2-u6-X10"}],"explanation":["먼저 위쪽으로 뒤집으면 위아래가 바뀌어요.","이어서 왼쪽으로 뒤집으면 좌우가 바뀌어요 — 좌우와 위아래가 모두 바뀌어요.","서로 다른 쪽으로 두 번 뒤집으면 처음으로 돌아오지 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,18.0],[36.0,18.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,18.0],[36.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[36.0,72.0],[36.0,36.0],[18.0,36.0],[18.0,18.0],[54.0,18.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,54.0],[72.0,54.0],[72.0,36.0],[54.0,36.0],[54.0,18.0],[36.0,18.0],[36.0,54.0],[18.0,54.0],[18.0,72.0],[54.0,72.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[36.0,54.0],[18.0,54.0],[18.0,36.0],[36.0,36.0],[36.0,18.0],[54.0,18.0],[54.0,54.0],[72.0,54.0],[72.0,72.0],[36.0,72.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"처음 도형을 아래쪽으로 두 번 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉰","mis":"M4-2-u6-X13"},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉮","mis":"M4-2-u6-X18"}],"explanation":["한 번 뒤집으면 위아래가 바뀌어요.","한 번 더 같은 쪽으로 뒤집으면 다시 바뀌어 제자리예요.","같은 쪽으로 두 번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":72,"h":90,"grid":18,"poly":[[[18.0,72.0],[36.0,72.0],[36.0,54.0],[54.0,54.0],[54.0,18.0],[18.0,18.0]]],"cap":"처음 도형"},{"w":72,"h":90,"grid":18,"poly":[[[54.0,18.0],[36.0,18.0],[36.0,36.0],[18.0,36.0],[18.0,72.0],[54.0,72.0]]],"cap":"㉮"},{"w":72,"h":90,"grid":18,"poly":[[[54.0,72.0],[36.0,72.0],[36.0,54.0],[18.0,54.0],[18.0,18.0],[54.0,18.0]]],"cap":"㉯"},{"w":72,"h":90,"grid":18,"poly":[[[18.0,18.0],[36.0,18.0],[36.0,36.0],[54.0,36.0],[54.0,72.0],[18.0,72.0]]],"cap":"㉰"},{"w":72,"h":90,"grid":18,"poly":[[[18.0,72.0],[36.0,72.0],[36.0,54.0],[54.0,54.0],[54.0,18.0],[18.0,18.0]]],"cap":"㉱"}],"tag":false}},{"stem":"처음 도형을 오른쪽으로 뒤집은 다음 아래쪽으로 뒤집었어요. 그 결과는 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉱","mis":"M4-2-u6-X13"},{"t":"㉮","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X10"}],"explanation":["먼저 오른쪽으로 뒤집으면 좌우가 바뀌어요.","이어서 아래쪽으로 뒤집으면 위아래가 바뀌어요 — 좌우와 위아래가 모두 바뀌어요.","서로 다른 쪽으로 두 번 뒤집으면 처음으로 돌아오지 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,54.0],[18.0,54.0]]],"cap":"처음 도형"},{"w":90,"h":72,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,54.0],[72.0,54.0]]],"cap":"㉮"},{"w":90,"h":72,"grid":18,"poly":[[[72.0,54.0],[36.0,54.0],[18.0,18.0],[72.0,18.0]]],"cap":"㉯"},{"w":90,"h":72,"grid":18,"poly":[[[18.0,54.0],[54.0,54.0],[72.0,18.0],[18.0,18.0]]],"cap":"㉰"},{"w":90,"h":72,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,54.0],[18.0,54.0]]],"cap":"㉱"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#19','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C7',3,'mc','auto','점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":19,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 반대 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 왼쪽에 있어요.","시계 반대 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":198,"h":108,"grid":18,"poly":[[[108.0,72.0],[126.0,18.0],[144.0,54.0],[180.0,54.0],[180.0,72.0]]],"dash":[[[18.0,18.0],[72.0,36.0]],[[72.0,36.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[18.0,90.0]],[[18.0,90.0],[18.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 아래쪽에 있어요.","시계 방향으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":144,"h":108,"grid":18,"poly":[[[90.0,90.0],[108.0,90.0],[108.0,72.0],[126.0,72.0],[126.0,54.0],[108.0,54.0],[108.0,18.0],[90.0,18.0]]],"dash":[[[54.0,18.0],[36.0,18.0]],[[36.0,18.0],[36.0,36.0]],[[36.0,36.0],[18.0,36.0]],[[18.0,36.0],[18.0,54.0]],[[18.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,90.0]],[[36.0,90.0],[54.0,90.0]],[[54.0,90.0],[54.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점선 도형을 돌렸더니 색칠한 도형이 되었어요. 어떻게 돌린 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 360°만큼 돌렸어요","mis":"M4-2-u6-X16"}],"explanation":["점선 도형의 위쪽에 있던 부분을 찾아요.","그 부분이 색칠한 도형에서는 오른쪽에 있어요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":162,"h":90,"grid":18,"poly":[[[144.0,18.0],[90.0,18.0],[90.0,54.0],[108.0,54.0],[108.0,36.0],[144.0,36.0]]],"dash":[[[18.0,18.0],[18.0,72.0]],[[18.0,72.0],[54.0,72.0]],[[54.0,72.0],[54.0,54.0]],[[54.0,54.0],[36.0,54.0]],[[36.0,54.0],[36.0,18.0]],[[36.0,18.0],[18.0,18.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#20','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C8',3,'mc','auto','아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X18']::text[],true,'{"seq":20,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X18"},{"t":"㉰","mis":"M4-2-u6-X18"},{"t":"㉱","mis":"M4-2-u6-X18"}],"explanation":["180°만큼 돌리면 위아래와 좌우가 모두 바뀌고, 아래쪽으로 뒤집으면 위아래만 바뀌어요.","그래서 왼쪽과 오른쪽이 똑같은 도형만 두 결과가 같아요.","㉮는 왼쪽과 오른쪽 모양이 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[36.0,54.0],[54.0,54.0],[54.0,72.0],[72.0,72.0],[72.0,54.0],[90.0,54.0],[90.0,36.0],[36.0,36.0]]],"cap":"㉮"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[90.0,72.0],[90.0,18.0],[36.0,18.0]]],"cap":"㉯"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[72.0,36.0],[90.0,72.0],[36.0,72.0]]],"cap":"㉰"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[90.0,36.0],[36.0,72.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형이 서로 같은 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M4-2-u6-X18"},{"t":"㉱","mis":"M4-2-u6-X18"},{"t":"㉮","mis":"M4-2-u6-X18"}],"explanation":["180°만큼 돌리면 위아래와 좌우가 모두 바뀌고, 아래쪽으로 뒤집으면 위아래만 바뀌어요.","그래서 왼쪽과 오른쪽이 똑같은 도형만 두 결과가 같아요.","㉰는 왼쪽과 오른쪽 모양이 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"poly":[[[36.0,36.0],[90.0,36.0],[36.0,72.0]]],"cap":"㉮"},{"w":126,"h":108,"grid":18,"poly":[[[36.0,18.0],[36.0,72.0],[54.0,72.0],[54.0,90.0],[72.0,90.0],[72.0,54.0],[54.0,54.0],[54.0,18.0]]],"cap":"㉯"},{"w":126,"h":108,"grid":18,"poly":[[[54.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,54.0],[63.0,90.0],[36.