INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_c#25','math',4,2,'u6','','g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',4,'essay','teacher','깃발 모양을 위쪽으로 3번, 아래쪽으로 2번 뒤집었어요. 한 친구는 「다섯 번이나 뒤집었으니 처음과 아주 달라졌을 거야.」라고 했어요. 친구의 말이 맞는지 쓰고, 결과가 어떤 도형과 같은지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C6","difficulty":4,"kind":"essay","stem":"깃발 모양을 위쪽으로 3번, 아래쪽으로 2번 뒤집었어요. 한 친구는 「다섯 번이나 뒤집었으니 처음과 아주 달라졌을 거야.」라고 했어요. 친구의 말이 맞는지 쓰고, 결과가 어떤 도형과 같은지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 친구의 말은 맞지 않다. 위쪽으로 뒤집기와 아래쪽으로 뒤집기는 결과가 같으므로 모두 5번 뒤집은 셈이다. 같은 쪽으로 두 번 뒤집으면 처음과 같아지므로 5번은 한 번 뒤집은 것과 같다. 그래서 결과는 처음 깃발을 위쪽(아래쪽)으로 한 번 뒤집은 도형과 같다.","scoring_points":["친구의 말이 틀렸다고 썼는가","위쪽·아래쪽 뒤집기는 같아 모두 5번이라고 썼는가","홀수 번이라 한 번 뒤집은 것과 같다고 썼는가"]},"explanation":["위쪽 뒤집기 = 아래쪽 뒤집기 — 모두 5번이에요.","두 번 뒤집을 때마다 처음으로 돌아와요.","5번은 한 번 뒤집은 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#1','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C1',1,'mc','auto','점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03','M4-2-u6-X01']::text[],true,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"아래쪽으로 2 cm","correct":true},{"t":"위쪽으로 2 cm","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 3 cm","mis":"M4-2-u6-X03"},{"t":"2 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 아래쪽에 있어요.","선을 넘을 때마다 하나씩 세면 2칸, 한 칸이 1 cm라서 2 cm예요.","점 ㄱ을 아래쪽으로 2 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[144,54,"n"],"ㄴ":[144,90,"s"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"오른쪽으로 4 cm","correct":true},{"t":"왼쪽으로 4 cm","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 5 cm","mis":"M4-2-u6-X03"},{"t":"4 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 오른쪽에 있어요.","선을 넘을 때마다 하나씩 세면 4칸, 한 칸이 1 cm라서 4 cm예요.","점 ㄱ을 오른쪽으로 4 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[72,54,"w"],"ㄴ":[144,54,"e"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ을 옮겼더니 점 ㄴ의 자리에 왔어요. 점 ㄱ을 어떻게 옮겼나요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"위쪽으로 2 cm","correct":true},{"t":"아래쪽으로 2 cm","mis":"M4-2-u6-X02"},{"t":"위쪽으로 3 cm","mis":"M4-2-u6-X03"},{"t":"2 cm","mis":"M4-2-u6-X01"}],"explanation":["나중 점 ㄴ이 처음 점 ㄱ보다 위쪽에 있어요.","선을 넘을 때마다 하나씩 세면 2칸, 한 칸이 1 cm라서 2 cm예요.","점 ㄱ을 위쪽으로 2 cm 옮겼어요 — 방향과 거리를 함께 말해요."],"asset":{"type":"geo","items":[{"w":180,"h":108,"grid":18,"pts":{"ㄱ":[36,54,"s"],"ㄴ":[36,18,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#2','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C2',1,'sa','auto','한 칸이 1 cm인 모눈에서 점을 아래쪽으로 2칸 옮겼어요. 점을 처음 자리로 되돌리려면 위쪽으로 몇 cm 옮겨야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u6-C2","difficulty":1,"kind":"sa","stem":"한 칸이 1 cm인 모눈에서 점을 아래쪽으로 2칸 옮겼어요. 점을 처음 자리로 되돌리려면 위쪽으로 몇 cm 옮겨야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["아래쪽과 위쪽은 서로 되돌리는 방향이에요.","같은 칸 수만큼 반대로 옮기면 처음 자리예요.","2칸 = 2 cm예요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm인 모눈에서 점을 왼쪽으로 3 cm 옮겼어요. 몇 칸 옮긴 것인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["모눈 한 칸은 1 cm예요.","3 cm는 1 cm가 3개예요.","3칸 옮긴 거예요."],"asset":null},{"stem":"한 칸이 1 cm인 모눈에서 점을 오른쪽으로 5칸 옮겼어요. 점을 처음 자리로 되돌리려면 왼쪽으로 몇 cm 옮겨야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["오른쪽과 왼쪽은 서로 되돌리는 방향이에요.","같은 칸 수만큼 반대로 옮기면 처음 자리예요.","5칸 = 5 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#3','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C3',1,'mc','auto','밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X02']::text[],true,'{"seq":3,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"왼쪽으로 밀었어요","correct":true},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 왼쪽에 있어요.","왼쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"poly":[[[36.0,36.0],[18.0,36.0],[18.0,54.0],[36.0,54.0],[36.0,72.0],[54.0,72.0],[54.0,36.0],[72.0,36.0],[72.0,18.0],[36.0,18.0]]],"dash":[[[126.0,36.0],[108.0,36.0]],[[108.0,36.0],[108.0,54.0]],[[108.0,54.0],[126.0,54.0]],[[126.0,54.0],[126.0,72.0]],[[126.0,72.0],[144.0,72.0]],[[144.0,72.0],[144.0,36.0]],[[144.0,36.0],[162.0,36.0]],[[162.0,36.0],[162.0,18.0]],[[162.0,18.0],[126.0,18.0]],[[126.0,18.0],[126.0,36.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"오른쪽으로 밀었어요","correct":true},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 오른쪽에 있어요.","오른쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":198,"h":72,"grid":18,"poly":[[[126.0,18.0],[162.0,18.0],[180.0,54.0],[126.0,54.0]]],"dash":[[[18.0,18.0],[54.0,18.0]],[[54.0,18.0],[72.0,54.0]],[[72.0,54.0],[18.0,54.0]],[[18.0,54.0],[18.0,18.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 밀기 전과 민 후의 도형을 보고 어느 쪽으로 밀었는지 고르세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"아래쪽으로 밀었어요","correct":true},{"t":"위쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 밀었어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 밀었어요","mis":"M4-2-u6-X02"}],"explanation":["점선(밀기 전)에서 색칠한 도형(민 후) 쪽을 봐요.","민 후의 도형이 밀기 전보다 아래쪽에 있어요.","아래쪽으로 밀었어요."],"asset":{"type":"geo","items":[{"w":72,"h":198,"grid":18,"poly":[[[18.0,180.0],[36.0,180.0],[36.0,162.0],[54.0,162.0],[54.0,126.0],[18.0,126.0]]],"dash":[[[18.0,72.0],[36.0,72.0]],[[36.0,72.0],[36.0,54.0]],[[36.0,54.0],[54.0,54.0]],[[54.0,54.0],[54.0,18.0]],[[54.0,18.0],[18.0,18.0]],[[18.0,18.0],[18.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#4','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C4',1,'sa','auto','삼각형을 위쪽으로 9칸 밀었어요. 아래쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u6-C4","difficulty":1,"kind":"sa","stem":"삼각형을 위쪽으로 9칸 밀었어요. 아래쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["9"],"explanation":["위쪽과 아래쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","아래쪽으로 9칸 밀면 처음 자리예요."],"variant_rule":{"alt":[{"stem":"삼각형을 오른쪽으로 7칸 밀었어요. 왼쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["7"],"explanation":["오른쪽과 왼쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","왼쪽으로 7칸 밀면 처음 자리예요."],"asset":null},{"stem":"삼각형을 아래쪽으로 5칸 밀었어요. 위쪽으로 몇 칸 밀면 처음 자리로 돌아오나요? 숫자로 쓰세요.","answer":["5"],"explanation":["아래쪽과 위쪽은 서로 되돌리는 방향이에요.","민 칸 수만큼 반대로 밀면 돼요.","위쪽으로 5칸 밀면 처음 자리예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#5','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C5',1,'mc','auto','도형의 위쪽에 있던 부분이 아래쪽으로 갔어요(왼쪽·오른쪽은 그대로예요). 어떻게 뒤집은 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],true,'{"seq":5,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"도형의 위쪽에 있던 부분이 아래쪽으로 갔어요(왼쪽·오른쪽은 그대로예요). 어떻게 뒤집은 것인가요?","options":[{"t":"위쪽이나 아래쪽으로 뒤집었어요","correct":true},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"아래쪽으로 밀었어요","mis":"M4-2-u6-X11"},{"t":"크기를 바꾸었어요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"variant_rule":{"alt":[{"stem":"도형을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"왼쪽과 오른쪽","correct":true},{"t":"위쪽과 아래쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null},{"stem":"도형을 위쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"위쪽과 아래쪽","correct":true},{"t":"왼쪽과 오른쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["뒤집는 쪽과 그 반대쪽이 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 좌우가, 위쪽·아래쪽으로 뒤집으면 위아래가 바뀌어요.","밀기는 자리만 바꿔요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#6','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C6',1,'mc','auto','깃발 모양을 오른쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X11']::text[],true,'{"seq":6,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"깃발 모양을 오른쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"왼쪽으로 뒤집기","correct":true},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"위쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"오른쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"variant_rule":{"alt":[{"stem":"사각형을 위쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"아래쪽으로 뒤집기","correct":true},{"t":"왼쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"오른쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"위쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null},{"stem":"도형을 왼쪽으로 뒤집은 것과 결과가 같은 것은 어느 것인가요?","options":[{"t":"오른쪽으로 뒤집기","correct":true},{"t":"위쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"아래쪽으로 뒤집기","mis":"M4-2-u6-X12"},{"t":"왼쪽으로 밀기","mis":"M4-2-u6-X11"}],"explanation":["위쪽·아래쪽으로 뒤집으면 둘 다 위아래가 서로 바뀌어요.","왼쪽·오른쪽으로 뒤집으면 둘 다 좌우가 서로 바뀌어요.","그래서 위쪽 = 아래쪽, 왼쪽 = 오른쪽 뒤집기는 결과가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#7','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',1,'mc','auto','집 모양의 오른쪽에 깃발이 있어요. 집 모양을 시계 방향으로 270°만큼 돌리면 깃발은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":7,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"집 모양의 오른쪽에 깃발이 있어요. 집 모양을 시계 방향으로 270°만큼 돌리면 깃발은 어느 쪽으로 가나요?","options":[{"t":"위쪽으로 가요","correct":true},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 270°만큼 돌리면 세 번 꺾어 270°.","오른쪽에서 시곗바늘 쪽으로 270°만큼 따라가 봐요.","깃발은 위쪽으로 가요."],"variant_rule":{"alt":[{"stem":"집 모양의 아래쪽에 창문이 있어요. 집 모양을 시계 반대 방향으로 90°만큼 돌리면 창문은 어느 쪽으로 가나요?","options":[{"t":"오른쪽으로 가요","correct":true},{"t":"왼쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","아래쪽에서 시곗바늘 반대쪽으로 90°만큼 따라가 봐요.","창문은 오른쪽으로 가요."],"asset":null},{"stem":"집 모양의 아래쪽에 굴뚝이 있어요. 집 모양을 시계 방향으로 90°만큼 돌리면 굴뚝은 어느 쪽으로 가나요?","options":[{"t":"왼쪽으로 가요","correct":true},{"t":"오른쪽으로 가요","mis":"M4-2-u6-X15"},{"t":"위쪽으로 가요","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 가요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 90°만큼 돌리면 한 번 꺾어 90°.","아래쪽에서 시곗바늘 쪽으로 90°만큼 따라가 봐요.","굴뚝은 왼쪽으로 가요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#8','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C9',1,'mc','auto','이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?',ARRAY['M4-2-u6-X19']::text[],true,'{"seq":8,"concept":"M4-2-u6-C9","difficulty":1,"kind":"mc","stem":"이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"아래쪽으로 뒤집기를 되풀이했어요","correct":true},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","위아래가 바뀐 두 모양이 번갈아 나와요.","아래쪽으로 뒤집기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[12.6,4.5],[12.6,18.6],[25.5,18.6],[25.5,25.5],[4.5,25.5]],[[34.5,25.5],[42.6,25.5],[42.6,11.4],[55.5,11.4],[55.5,4.5],[34.5,4.5]],[[64.5,4.5],[72.6,4.5],[72.6,18.6],[85.5,18.6],[85.5,25.5],[64.5,25.5]],[[94.5,25.5],[102.6,25.5],[102.6,11.4],[115.5,11.4],[115.5,4.5],[94.5,4.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"오른쪽으로 뒤집기를 되풀이했어요","correct":true},{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"아래쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explanation":["맨 왼쪽 칸과 그 옆 칸을 견주어 어떻게 움직였는지 봐요.","뒤집을 때마다 좌우가 바뀌어 두 모양이 번갈아 나와요.","오른쪽으로 뒤집기를 되풀이했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[4.5,4.5],[25.5,4.5],[4.5,16.5]],[[55.5,4.5],[34.5,4.5],[55.5,16.5]],[[64.5,4.5],[85.5,4.5],[64.5,16.5]],[[115.5,4.5],[94.5,4.5],[115.5,16.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 한 줄은 맨 왼쪽 모양으로 어떻게 만들었나요?","options":[{"t":"시계 방향으로 90°씩 돌리기를 되풀이했어요","correct":true},{"t":"오른쪽으로 밀기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"오른쪽으로 뒤집기를 되풀이했어요","mis":"M4-2-u6-X19"},{"t":"시계 방향으로 180°씩 돌리기를 되풀이했어요","mis":"M4-2-u6-X19"}],"explana