INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u6_review_d#25','math',4,2,'u6','','g4_2_math_u6_review_d','unit_review','M4-2-u6-C8',4,'essay','teacher','퍼즐 조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳에 꼭 맞아요. 로니는 시계 방향으로만 돌릴 수 있어요. 로니에게 어떻게 말해 주어야 하는지 쓰고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"퍼즐 조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳에 꼭 맞아요. 로니는 시계 방향으로만 돌릴 수 있어요. 로니에게 어떻게 말해 주어야 하는지 쓰고, 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 「조각을 시계 방향으로 270°만큼 돌려.」라고 말해 준다. 한 바퀴는 360°이므로 시계 반대 방향으로 90°만큼 돌린 것은 시계 방향으로 360° − 90° = 270°만큼 돌린 것과 결과가 같다. 방향과 각도를 함께 말해야 로니가 알아듣는다.","scoring_points":["시계 방향으로 270°라고 썼는가","360° − 90° = 270°로 까닭을 썼는가","방향과 각도를 함께 말했는가"]},"explanation":["한 바퀴는 360°예요.","시계 반대 90° = 시계 360° − 90° = 270°.","「시계 방향으로 270°만큼 돌려.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
